import React,{useEffect,useState} from 'react';import{createRoot}from'react-dom/client';import{Activity,AlertTriangle,BarChart3,Bell,Camera,Check,ChevronRight,Clock3,Cpu,Download,Eye,LayoutDashboard,Radio,RefreshCw,Search,Settings,ShieldAlert,SlidersHorizontal,Video,Wifi,WifiOff,X,Users,BrainCircuit,Play,FileWarning,Database,Palette,Sun,Moon,Monitor,PanelLeft,KeyRound,Stethoscope,Plus,Trash2,Pencil,Save}from'lucide-react';import'./styles.css';

type Dashboard={cameras:{total:number,online:number},events24h:number,critical_unacked:number,avg_fps:number,avg_latency_ms:number,gpu_load:number|null,gpu_temp:number|null,messenger_provider:string,active_model:string|null,precision:number|null,recall:number|null,trend:{label:string,value:number}[]};
type Cam={id:string,name:string,zone:string,description:string,status:string,fps:number,latency_ms:number,fps_limit:number,enabled:number,configured:number,snapshot_age_seconds?:number|null,telemetry_stale?:boolean,last_error?:string,restart_requested_at?:string};
type Event={id:number,timestamp:string,camera_id:string,camera_name:string,zone:string,type:string,severity:string,confidence:number,person_id:string,acknowledged:number,has_frame?:boolean,note?:string,review_status?:'pending'|'accepted'|'rejected',reviewed_at?:string};
type Model={name:string,format:string,status:string,precision:number|null,recall:number|null,trained_at:string,source:string,active:boolean,trial_eligible?:boolean,trial_mode?:boolean};
type Job={id:number,camera_id:string,target_name:string,image_count:number,epochs:number,status:string,progress:number,stage:string,created_at:string,error?:string,source?:string,dataset_name?:string};
type Dataset={id:number,name:string,path:string,image_count:number,class_count:number,media_count?:number,kind?:string,created_at:string,exists:boolean};
type CaptureJob={id:number,name:string,camera_id:string,target_count:number,capture_fps:number,status:string,captured_count:number,stage:string,error?:string,created_at:string};
const KIND_LABEL:Record<string,string>={yolo:'YOLO-датасет',images:'Фото',videos:'Видео'};
const STATUS_LABEL:Record<string,string>={connecting:'Подключение',online:'Онлайн',offline:'Офлайн',recovering:'Восстановление',error:'Ошибка',unknown:'Неизвестно'};
type Log={id:number,timestamp:string,level:string,service:string,message:string,camera_id?:string};
type Capability={demo_mode:boolean,training_worker:boolean,training?:{reachable:boolean,gpu:boolean,device?:string,configured?:boolean},external_inference_gateway:boolean,camera_crud:boolean,diagnostics:boolean,search:boolean};
type SearchItem={kind:string,id:string|number,title:string,subtitle:string};
type ChartDatum={label:string,value:number,detail?:string};
type Analytics={generated_at:string,hours:number,bucket:'hour'|'day',period:{from:string,to:string},totals:{events:number,critical:number,pending:number,accepted:number,rejected:number,avg_confidence:number},buckets:{start:string,label:string,total:number,critical:number,pending:number,accepted:number,rejected:number,avg_confidence:number}[],types:{id:string,label:string,value:number}[],cameras:{camera_id:string,name:string,zone:string,total:number,critical:number,pending:number,accepted:number,rejected:number}[],review:{id:'pending'|'accepted'|'rejected',label:string,value:number}[],severity:{id:string,label:string,value:number}[]};
const readJson=(key:string)=>{try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{localStorage.removeItem(key);return {}}};
const uiDefaults={theme:'system',accent:'lime',density:'comfortable',sidebar:'full',corners:'soft',motion:'full',cameraFit:'cover',refreshSeconds:5,overviewPeriod:24,overviewChart:'trend',overviewStyle:'bar'};
const applyUi=(next:any)=>{const all={...uiDefaults,...next};localStorage.setItem('zmk_ui',JSON.stringify(all));const dark=all.theme==='dark'||(all.theme==='system'&&matchMedia('(prefers-color-scheme:dark)').matches);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.density=all.density;document.documentElement.dataset.sidebar=all.sidebar;document.documentElement.dataset.motion=all.motion;document.documentElement.dataset.cameraFit=all.cameraFit;document.documentElement.dataset.corners=all.corners;document.documentElement.style.setProperty('--accent',({lime:'#d5ff45',blue:'#69a7ff',orange:'#ffad4d',violet:'#a98cff'} as any)[all.accent]||'#d5ff45');return all};
const loadTelegramSdk=()=>new Promise<void>(resolve=>{if((window as any).Telegram?.WebApp)return resolve();const existing=document.querySelector('script[data-telegram-sdk]') as HTMLScriptElement|null;if(existing){existing.addEventListener('load',()=>resolve(),{once:true});setTimeout(resolve,3000);return}const script=document.createElement('script');script.src='https://telegram.org/js/telegram-web-app.js';script.dataset.telegramSdk='true';script.onload=()=>resolve();script.onerror=()=>resolve();document.head.appendChild(script);setTimeout(resolve,3000)});
const downloadFile=async(url:string,name:string)=>{const key=localStorage.getItem('zmk_api_key')||'';const tgData=(window as any).Telegram?.WebApp?.initData||'';const headers:Record<string,string>={};if(key)headers['X-API-Key']=key;if(tgData)headers['X-Telegram-Init-Data']=tgData;const r=await fetch(url,{headers});if(!r.ok)throw new Error('Не удалось скачать файл');const blob=await r.blob();const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)};
const labels:Record<string,string>={no_helmet:'Без каски',no_vest:'Без жилета',phone_usage:'Телефон',smoking:'Курение',restricted_zone:'Опасная зона',immobility:'Неподвижность'};
const api=async<T,>(url:string,opts?:RequestInit):Promise<T>=>{const key=localStorage.getItem('zmk_api_key')||'';const tgData=(window as any).Telegram?.WebApp?.initData||'';const headers=new Headers(opts?.headers);if(key)headers.set('X-API-Key',key);if(tgData)headers.set('X-Telegram-Init-Data',tgData);const r=await fetch(url,{...opts,headers});if(!r.ok)throw new Error(await r.text());return r.json()};
function Spark({data}:{data:{label:string,value:number}[]}){const max=Math.max(...data.map(x=>x.value),1);return <div className="spark">{data.map((x,i)=><div key={i} className="barwrap"><div className="bar" style={{height:`${Math.max(8,x.value/max*100)}%`}}/><span>{i%2===0?x.label:''}</span></div>)}</div>}
function App(){
 const[tab,setTab]=useState('Обзор');const[customize,setCustomize]=useState(false);const[d,setD]=useState<Dashboard|null>(null);const[cams,setCams]=useState<Cam[]>([]);const[events,setEvents]=useState<Event[]>([]);const[loading,setLoading]=useState(true);const[toast,setToast]=useState('');const[error,setError]=useState('');const[query,setQuery]=useState('');const[searchResults,setSearchResults]=useState<SearchItem[]>([]);const[ver,setVer]=useState('');const[upd,setUpd]=useState<{available:boolean;current?:string;latest?:string;reason?:string}|null>(null);const[updBusy,setUpdBusy]=useState(false);const checkUpdate=async()=>{try{const s=await api<{available:boolean;current:string;latest:string;update_available:boolean;reason?:string}>('/api/update/status');setUpd({available:s.available,current:s.current||ver,latest:s.latest,reason:s.reason});if(s.update_available){setToast(`Доступна версия ${s.latest}`);setTimeout(()=>setToast(''),2600)}else if(s.available){setToast('Установлена последняя версия');setTimeout(()=>setToast(''),2600)}else{setToast(s.reason||'Служба обновления недоступна');setTimeout(()=>setToast(''),3200)}}catch(e){setToast(e instanceof Error?e.message:'Не удалось проверить обновления');setTimeout(()=>setToast(''),3200)}};const runUpdate=async()=>{setUpdBusy(true);try{const r=await api<{status:string;message:string}>('/api/update/apply',{method:'POST'});setToast(r.message||(r.status==='updated'?'Обновление применяется...':r.status));setTimeout(()=>setToast(''),r.status==='updated'?5000:3200);if(r.status!=='updated')await checkUpdate()}catch(e){setToast(e instanceof Error?e.message:'Ошибка запуска обновления');setTimeout(()=>setToast(''),3200)}finally{setUpdBusy(false)}};
 const load=async()=>{setLoading(true);setError('');try{const[a,b,c]=await Promise.all([api<Dashboard>('/api/dashboard'),api<Cam[]>('/api/cameras'),api<Event[]>('/api/events?limit=200')]);setD(a);setCams(b);setEvents(c)}catch(e){setError(e instanceof Error?e.message:'Сервис временно недоступен')}finally{setLoading(false)}};
 const refreshSeconds=Math.min(60,Math.max(3,Number(readJson('zmk_ui').refreshSeconds)||5));
 useEffect(()=>{load();api<any>('/api/health').then(h=>setVer(h.version||'')).catch(()=>{});checkUpdate();const t=setInterval(load,refreshSeconds*1000);return()=>clearInterval(t)},[refreshSeconds]);
 useEffect(()=>{if(query.trim().length<2){setSearchResults([]);return}const t=setTimeout(()=>api<{results:SearchItem[]}>(`/api/search?q=${encodeURIComponent(query)}`).then(x=>setSearchResults(x.results)).catch(()=>setSearchResults([])),250);return()=>clearTimeout(t)},[query]);
 const ack=async(id:number)=>{const note='Проверено оператором';try{await api(`/api/events/${id}/ack`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note})});setEvents(v=>v.map(e=>e.id===id?{...e,acknowledged:1,review_status:'accepted',note}:e));setToast('Событие подтверждено');setTimeout(()=>setToast(''),2200)}catch(e){setError(e instanceof Error?e.message:'Не удалось подтвердить событие')}};
 const reject=async(id:number,note:string)=>{const finalNote=note.trim()||'Не принято оператором';try{await api(`/api/events/${id}/reject`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({note:finalNote})});setEvents(v=>v.map(e=>e.id===id?{...e,acknowledged:1,review_status:'rejected',note:finalNote}:e));setToast('Событие отклонено');setTimeout(()=>setToast(''),2200)}catch(e){setError(e instanceof Error?e.message:'Не удалось отклонить событие');throw e}};
 const ackMany=async(ids:number[],note:string)=>{try{const result=await api<{acknowledged_ids:number[],already_acknowledged_ids:number[]}>('/api/events/ack-bulk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_ids:ids,note})});const done=new Set([...result.acknowledged_ids,...result.already_acknowledged_ids]);const finalNote=note.trim()||'Проверено оператором';setEvents(v=>v.map(e=>done.has(e.id)?{...e,acknowledged:1,review_status:'accepted',note:finalNote}:e));setToast(`Принято событий: ${done.size}`);setTimeout(()=>setToast(''),2600);return [...done]}catch(e){setError(e instanceof Error?e.message:'Не удалось подтвердить события');throw e}};
 const rejectMany=async(ids:number[],note:string)=>{try{const result=await api<{rejected_ids:number[],already_rejected_ids:number[]}>('/api/events/reject-bulk',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({event_ids:ids,note})});const done=new Set([...result.rejected_ids,...result.already_rejected_ids]);const finalNote=note.trim()||'Не принято оператором';setEvents(v=>v.map(e=>done.has(e.id)?{...e,acknowledged:1,review_status:'rejected',note:finalNote}:e));setToast(`Отклонено событий: ${done.size}`);setTimeout(()=>setToast(''),2600);return [...done]}catch(e){setError(e instanceof Error?e.message:'Не удалось отклонить события');throw e}};
 const openResult=(item:SearchItem)=>{setTab(item.kind==='camera'?'Камеры':item.kind==='model'?'Модели':'События');setQuery('');setSearchResults([])};
 const nav=[['Обзор',LayoutDashboard],['Камеры',Video],['События',ShieldAlert],['Модели',Cpu],['Диагностика',Stethoscope],['Админ',Users],['Настройки',Settings]] as const;
 const content=tab==='Камеры'?<Cameras cams={cams} changed={load}/>:tab==='События'?<Events events={events} ack={ack} reject={reject} ackMany={ackMany} rejectMany={rejectMany}/>:tab==='Модели'?<Models cams={cams}/>:tab==='Диагностика'?<Diagnostics/>:tab==='Админ'?<Admin/>:tab==='Настройки'?<Config/>:<Overview d={d} cams={cams} events={events} ack={ack} openDiagnostics={()=>setTab('Диагностика')} openTab={setTab}/>;
 return <div className="app"><aside><div className="brand"><div className="brandmark"><Eye size={22}/></div><div><b>ZMK VISION</b><small>Центр видеоаналитики</small></div></div><nav>{nav.map(([n,I])=><button className={tab===n?'active':''} onClick={()=>setTab(n)} key={n}><I size={19}/><span>{n}</span>{n==='События'&&d?.critical_unacked?<em>{d.critical_unacked}</em>:null}</button>)}</nav><div className="side-status"><div><span className="pulse"/> API подключён</div><small>Версия {ver||'…'} • {d?.messenger_provider==='max'?'MAX':d?.messenger_provider==='telegram'?'Telegram':'без бота'}</small></div><div className="profile"><div className="avatar">LO</div><div><b>Локальный оператор</b><small>Доступ по API key</small></div></div></aside><main><header><div><h1>{tab}</h1><p>Контроль камер, событий и интеграций</p></div><div className="head-actions"><div className="search"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Поиск камер, событий, моделей"/>{query&&<button onClick={()=>setQuery('')}><X size={14}/></button>}{searchResults.length>0&&<div className="search-results">{searchResults.map(x=><button key={`${x.kind}-${x.id}`} onClick={()=>openResult(x)}><b>{x.title}</b><small>{x.subtitle}</small></button>)}</div>}</div><button className="icon" title="События" onClick={()=>setTab('События')}><Bell size={19}/>{d?.critical_unacked?<i/>:null}</button><button className="icon" title="Персонализация" onClick={()=>setCustomize(true)}><Palette size={19}/></button><button className={`icon upbtn ${upd?.available?'has-update':''}`} title="Проверить обновление" onClick={checkUpdate}><Download size={19}/>{upd?.available?<i/>:null}</button>{upd?.available&&<button className="refresh updater" disabled={updBusy} onClick={runUpdate}><Download size={16}/> {updBusy?'Обновляю…':'Обновить'} {upd.latest}</button>}<button className="refresh" onClick={load}><RefreshCw className={loading?'spin':''} size={17}/> Обновить</button></div></header><section>{error&&<div className="api-error"><AlertTriangle/><span><b>Не удалось получить данные</b><small>{error}</small></span><button onClick={load}>Повторить</button></div>}{content}</section></main>{toast&&<div className="toast"><Check size={17}/>{toast}</div>}{customize&&<Customizer close={()=>setCustomize(false)}/>}</div>
}
function Metric({icon:I,label,value,unit,accent,delta}:{icon:any,label:string,value:string|number|null,unit?:string,accent:string,delta:string}){return <article className="metric"><div className={`mi ${accent}`}><I size={21}/></div><div className="metric-top"><span>{label}</span><b>{value??'—'}<small>{value===null?'':unit}</small></b></div><div className="delta"><Activity size={13}/>{delta}</div></article>}
function analyticsSvg(title:string,data:ChartDatum[],style:'bar'|'line'){const width=1000,height=520,left=64,right=32,top=56,bottom=78,innerW=width-left-right,innerH=height-top-bottom,max=Math.max(...data.map(item=>item.value),1),escape=(value:string)=>value.replace(/[&<>"']/g,char=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&apos;"}[char]||char)),x=(index:number)=>left+(data.length<=1?innerW/2:index*innerW/(data.length-1)),y=(value:number)=>top+innerH-(value/max)*innerH,labels=data.map((item,index)=>index%Math.max(1,Math.ceil(data.length/8))===0?`<text x="${style==='bar'?left+(index+.5)*innerW/Math.max(1,data.length):x(index)}" y="${height-40}" text-anchor="middle" font-size="12" fill="#52635b">${escape(item.label)}</text>`:'').join('');const chart=style==='line'?`<polyline fill="none" stroke="#4f9b66" stroke-width="4" points="${data.map((item,index)=>`${x(index)},${y(item.value)}`).join(' ')}"/>${data.map((item,index)=>`<circle cx="${x(index)}" cy="${y(item.value)}" r="5" fill="#d5ff45" stroke="#2a6d43" stroke-width="2"><title>${escape(`${item.label}: ${item.value}`)}</title></circle>`).join('')}`:data.map((item,index)=>{const barW=Math.max(8,innerW/Math.max(1,data.length)*.65),barX=left+index*innerW/Math.max(1,data.length)+(innerW/Math.max(1,data.length)-barW)/2,barY=y(item.value);return `<rect x="${barX}" y="${barY}" width="${barW}" height="${top+innerH-barY}" rx="4" fill="#5fa872"><title>${escape(`${item.label}: ${item.value}`)}</title></rect>`}).join('');return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}"><rect width="100%" height="100%" fill="#ffffff"/><text x="${left}" y="30" font-size="22" font-family="Arial, sans-serif" fill="#17211d" font-weight="700">${escape(title)}</text><line x1="${left}" y1="${top+innerH}" x2="${width-right}" y2="${top+innerH}" stroke="#cbd7d0"/><line x1="${left}" y1="${top}" x2="${left}" y2="${top+innerH}" stroke="#cbd7d0"/><text x="${left-12}" y="${top+8}" text-anchor="end" font-size="12" fill="#52635b">${max}</text><text x="${left-12}" y="${top+innerH}" text-anchor="end" font-size="12" fill="#52635b">0</text>${chart}${labels}</svg>`}
function downloadAnalyticsSvg(title:string,data:ChartDatum[],style:'bar'|'line'){const blob=new Blob([analyticsSvg(title,data,style)],{type:'image/svg+xml;charset=utf-8'});const href=URL.createObjectURL(blob);const link=document.createElement('a');link.href=href;link.download=`zmk-${title.toLowerCase().replace(/[^a-z0-9а-я]+/gi,'-')}.svg`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)}
function AnalyticsChart({title,data,style}:{title:string,data:ChartDatum[],style:'bar'|'line'}){if(!data.length)return <div className="analytics-empty">За выбранный период данных пока нет</div>;const max=Math.max(...data.map(item=>item.value),1),width=760,height=270,left=40,right=12,top=18,bottom=48,innerW=width-left-right,innerH=height-top-bottom,labelEvery=Math.max(1,Math.ceil(data.length/8)),x=(index:number)=>left+(style==='bar'?(index+.5)*innerW/data.length:(data.length<=1?innerW/2:index*innerW/(data.length-1))),y=(value:number)=>top+innerH-(value/max)*innerH;return <svg className="analytics-chart" viewBox={`0 0 ${width} ${height}`} role="img" aria-label={title}><line x1={left} y1={top+innerH} x2={width-right} y2={top+innerH}/><line x1={left} y1={top} x2={left} y2={top+innerH}/><text x={left-6} y={top+8} textAnchor="end">{max}</text><text x={left-6} y={top+innerH} textAnchor="end">0</text>{style==='line'?<><polyline className="analytics-line" points={data.map((item,index)=>`${x(index)},${y(item.value)}`).join(' ')}/>{data.map((item,index)=><g key={item.label}><circle className="analytics-dot" cx={x(index)} cy={y(item.value)} r="4"><title>{`${item.label}: ${item.value}`}</title></circle>{index%labelEvery===0&&<text className="analytics-label" x={x(index)} y={height-18} textAnchor="middle">{item.label}</text>}</g>)}</>:data.map((item,index)=>{const barW=Math.max(7,innerW/data.length*.64),barX=left+index*innerW/data.length+(innerW/data.length-barW)/2,barY=y(item.value);return <g key={item.label}><rect className="analytics-bar" x={barX} y={barY} width={barW} height={top+innerH-barY} rx="3"><title>{`${item.label}: ${item.value}`}</title></rect>{index%labelEvery===0&&<text className="analytics-label" x={barX+barW/2} y={height-18} textAnchor="middle">{item.label}</text>}</g>})}</svg>}
function OverviewKpi({icon:Icon,label,value,detail,tone}:{icon:any,label:string,value:string|number,detail:string,tone:'green'|'amber'|'red'|'blue'}){return <article className={`overview-kpi ${tone}`}><div className="overview-kpi-icon"><Icon size={18}/></div><div><small>{label}</small><b>{value}</b><span>{detail}</span></div></article>}
function Overview({d,cams,events,ack,openDiagnostics,openTab}:{d:Dashboard|null,cams:Cam[],events:Event[],ack:(id:number)=>void,openDiagnostics:()=>void,openTab:(tab:string)=>void}){const ui=readJson('zmk_ui');const defaultPeriod=[24,168,720].includes(Number(ui.overviewPeriod))?Number(ui.overviewPeriod):24;const defaultChart=['trend','types','cameras','review','severity'].includes(ui.overviewChart)?ui.overviewChart:'trend';const defaultStyle=ui.overviewStyle==='line'?'line':'bar';const[hours,setHours]=useState(defaultPeriod);const[customHours,setCustomHours]=useState(String(defaultPeriod));const[bucket,setBucket]=useState<'auto'|'hour'|'day'>('auto');const[chartMode,setChartMode]=useState<'trend'|'types'|'cameras'|'review'|'severity'>(defaultChart);const[chartStyle,setChartStyle]=useState<'bar'|'line'>(defaultStyle);const[analytics,setAnalytics]=useState<Analytics|null>(null);const[analyticsError,setAnalyticsError]=useState('');const[analyticsLoading,setAnalyticsLoading]=useState(false);const loadAnalytics=async()=>{setAnalyticsLoading(true);setAnalyticsError('');try{setAnalytics(await api<Analytics>(`/api/analytics/overview?hours=${hours}&bucket=${bucket}`))}catch(e){setAnalyticsError(e instanceof Error?e.message:'Не удалось загрузить статистику')}finally{setAnalyticsLoading(false)}};useEffect(()=>{void loadAnalytics()},[hours,bucket]);if(!d)return <div className="loader"/>;const periodLabel=hours===24?'24 часа':hours===168?'7 дней':hours===720?'30 дней':`${hours} ч`;const chartData:ChartDatum[]=!analytics?[]:chartMode==='trend'?analytics.buckets.map(item=>({label:item.label,value:item.total,detail:`Критических: ${item.critical}`})):chartMode==='types'?analytics.types.map(item=>({label:item.label,value:item.value})):chartMode==='cameras'?analytics.cameras.map(item=>({label:item.name,value:item.total,detail:item.zone})):chartMode==='review'?analytics.review.map(item=>({label:item.label,value:item.value})):analytics.severity.map(item=>({label:item.label,value:item.value}));const chartTitle=chartMode==='trend'?'Динамика событий':chartMode==='types'?'Нарушения по типам':chartMode==='cameras'?'События по камерам':chartMode==='review'?'Решения оператора':'Распределение критичности';const applyCustom=()=>{const next=Math.max(1,Math.min(2160,Number(customHours)||24));setCustomHours(String(next));setHours(next)};const decisionTotal=(analytics?.totals.pending||0)+(analytics?.totals.accepted||0)+(analytics?.totals.rejected||0);return <div className="overview-page"><div className="statusline overview-status"><div><span className="pulse"/><b>Контур видеоаналитики активен</b><span>{d.cameras.online}/{d.cameras.total} камер онлайн · обновление статистики в реальном времени</span></div><button onClick={openDiagnostics}>Диагностика <ChevronRight size={15}/></button></div><article className="overview-hero"><div className="overview-hero-copy"><span className="overview-eyebrow">ZMK VISION · АНАЛИТИКА</span><h2>Аналитика площадки</h2><p>Настройте период, вид диаграммы и экспортируйте готовые данные для отчёта.</p><div className="overview-hero-meta"><span><Clock3 size={14}/>{periodLabel}</span><span><Activity size={14}/>{analytics?.totals.events??0} событий</span><span><ShieldAlert size={14}/>{analytics?.totals.pending??0} требуют решения</span></div></div><div className="overview-hero-actions"><button onClick={loadAnalytics} disabled={analyticsLoading}><RefreshCw size={15} className={analyticsLoading?'spin':''}/> Обновить данные</button><button disabled={!chartData.length} onClick={()=>downloadAnalyticsSvg(chartTitle,chartData,chartStyle)}><Download size={15}/> SVG</button><button className="primary" onClick={()=>downloadFile(`/api/reports/analytics.csv?hours=${hours}&bucket=${bucket}`,`zmk-analytics-${hours}h.csv`).catch(()=>{})}><Download size={15}/> CSV отчёт</button></div></article><div className="overview-controls"><div className="overview-control-group"><span>Период</span><div className="period-group">{[[24,'24 ч'],[168,'7 дней'],[720,'30 дней']].map(([value,label])=><button key={value} className={hours===value?'active':''} onClick={()=>{setHours(value as number);setCustomHours(String(value))}}>{label}</button>)}</div></div><label className="overview-custom-period"><span>Свой период, ч</span><div><input type="number" min="1" max="2160" value={customHours} onChange={e=>setCustomHours(e.target.value)}/><button onClick={applyCustom}>Применить</button></div></label><label><span>Группировка</span><select value={bucket} onChange={e=>setBucket(e.target.value as 'auto'|'hour'|'day')}><option value="auto">Автоматически</option><option value="hour">По часам</option><option value="day">По дням</option></select></label><label><span>Диаграмма</span><select value={chartMode} onChange={e=>setChartMode(e.target.value as typeof chartMode)}><option value="trend">Динамика</option><option value="types">Типы нарушений</option><option value="cameras">Камеры</option><option value="review">Решения</option><option value="severity">Критичность</option></select></label><label><span>Вид</span><select value={chartStyle} onChange={e=>setChartStyle(e.target.value as 'bar'|'line')}><option value="bar">Столбцы</option><option value="line">Линия</option></select></label></div>{analyticsError&&<div className="analytics-error">{analyticsError}</div>}<div className="overview-kpis"><OverviewKpi icon={Camera} label="Камеры онлайн" value={`${d.cameras.online}/${d.cameras.total}`} detail="Текущее подключение" tone="green"/><OverviewKpi icon={ShieldAlert} label="События" value={analytics?.totals.events??'—'} detail={`За ${periodLabel}`} tone="amber"/><OverviewKpi icon={AlertTriangle} label="Критические" value={analytics?.totals.critical??d.critical_unacked} detail={`Ожидают: ${analytics?.totals.pending??'—'}`} tone="red"/><OverviewKpi icon={Cpu} label="Средняя уверенность" value={`${Math.round((analytics?.totals.avg_confidence??0)*100)}%`} detail={d.gpu_temp===null?'CPU / GPU не обнаружен':`GPU ${d.gpu_temp} °C`} tone="blue"/></div><div className="overview-analytics-grid"><article className="panel overview-chart-card"><PanelTitle title={chartTitle} sub={`${periodLabel} · ${analytics?.bucket==='day'?'по дням':'по часам'}`} action="Обновить" onAction={loadAnalytics}/>{analyticsLoading&&!analytics?<div className="analytics-loading"><RefreshCw className="spin"/> Загружаю статистику…</div>:<AnalyticsChart title={chartTitle} data={chartData} style={chartStyle}/>}<div className="overview-chart-foot"><span><i/>Всего событий</span><span><i className="critical"/>Критические: {analytics?.totals.critical??0}</span><b>{Math.round((analytics?.totals.avg_confidence??0)*100)}%<small> средняя уверенность</small></b></div></article><article className="panel overview-review-card"><PanelTitle title="Состояние проверки" sub={`Решения оператора · ${periodLabel}`}/><div className="review-donut" style={{'--pending':`${Math.round((analytics?.totals.pending??0)/Math.max(1,decisionTotal)*100)}%`,'--accepted':`${Math.round((analytics?.totals.accepted??0)/Math.max(1,decisionTotal)*100)}%`} as React.CSSProperties}><div><b>{decisionTotal}</b><small>всего</small></div></div><div className="review-summary polished"><span><i className="pending"/><b>{analytics?.totals.pending??0}</b><small>Ожидают</small></span><span><i className="accepted"/><b>{analytics?.totals.accepted??0}</b><small>Принято</small></span><span><i className="rejected"/><b>{analytics?.totals.rejected??0}</b><small>Не принято</small></span></div><div className="overview-model-health"><div><BrainCircuit size={16}/><span><b>{d.active_model||'Модель не выбрана'}</b><small>{d.active_model?'Активный аналитический контур':'Включите модель на вкладке «Модели»'}</small></span></div><em>{d.avg_latency_ms} мс</em></div></article></div><div className="overview-lower-grid"><article className="panel"><PanelTitle title="Последние события" sub="Обновляется автоматически" action="Все события" onAction={()=>openTab('События')}/><EventsTable events={events.slice(0,5)} ack={ack}/></article><article className="panel"><PanelTitle title="Статус камер" sub={`${d.cameras.online} из ${d.cameras.total} подключены`} action="Все камеры" onAction={()=>openTab('Камеры')}/><div className="camlist">{cams.slice(0,5).map(c=><div className="camrow" key={c.id}><div className="thumb"><Camera size={18}/><span className={c.status}/></div><div><b>{c.name}</b><small>{c.zone}</small></div><div className="cammetric"><b>{c.status==='online'?`${c.fps} FPS`:'Нет сигнала'}</b><small>{c.status==='online'?`${c.latency_ms} мс`:'Проверьте RTSP'}</small></div><div className={`tag ${c.status}`}>{c.status==='online'?<Wifi size={12}/>:<WifiOff size={12}/>} {STATUS_LABEL[c.status]||'Офлайн'}</div></div>)}</div></article></div></div>}
function PanelTitle({title,sub,action,onAction}:{title:string,sub:string,action?:string,onAction?:()=>void}){return <div className="pt"><div><h3>{title}</h3><p>{sub}</p></div>{action&&<button onClick={onAction} disabled={!onAction}>{action}<ChevronRight size={14}/></button>}</div>}
function Ring({value,label}:{value:number,label:string}){return <div className="ringbox"><div className="ring" style={{'--p':`${value*3.6}deg`} as React.CSSProperties}><span>{value}<small>%</small></span></div><b>{label}</b><small>Цель ≥ {label==='Precision'?90:85}%</small></div>}
function EventsTable({events,ack,onReject,openEvidence,selectionMode=false,selectedIds=[],onToggle}:{events:Event[],ack:(id:number)=>void,onReject?:(event:Event)=>void,openEvidence?:(event:Event)=>void,selectionMode?:boolean,selectedIds?:number[],onToggle?:(id:number)=>void}){return <div className="table"><div className="tr th"><span>Событие</span><span>Камера / зона</span><span>Уверенность</span><span>Время</span><span/></div>{events.map(e=>{const selected=selectedIds.includes(e.id);const review=e.review_status||(e.acknowledged?'accepted':'pending');return <div className={`tr ${selected?'selected-event':''} ${review==='rejected'?'rejected-event':''}`} key={e.id}><span><i className={`sev ${e.severity}`}/><b>{labels[e.type]||e.type}</b><small>{e.note||e.person_id||'Объект не указан'}</small></span><span><b>{e.camera_name||e.camera_id}</b><small>{e.zone||'—'}</small></span><span><b>{Math.round(e.confidence*100)}%</b><small className="conf"><i style={{width:`${e.confidence*100}%`}}/></small></span><span><b>{new Date(e.timestamp).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</b><small>{new Date(e.timestamp).toLocaleDateString('ru-RU')}</small></span><span className="event-actions">{selectionMode&&onToggle?<button className={`event-select ${selected?'selected':''}`} onClick={()=>onToggle(e.id)}>{selected?<Check size={13}/>:<Plus size={13}/>} {selected?'Выбрано':'Выбрать'}</button>:<>{openEvidence&&e.has_frame&&<button className="evidence" title="Открыть кадр события" onClick={()=>openEvidence(e)}><Eye size={13}/> Кадр</button>}{review==='rejected'?<span className="rejected"><X size={13}/> Не принято</span>:review==='accepted'?<span className="done"><Check size={13}/> Принято</span>:<><button className="ack" onClick={()=>ack(e.id)}>Принять</button>{onReject&&<button className="reject-event" onClick={()=>onReject(e)}><X size={13}/> Не принять</button>}</>}</>}</span></div>})}</div>}
function EventEvidenceModal({event,close}:{event:Event,close:()=>void}){const[src,setSrc]=useState('');const[error,setError]=useState('Загружаю кадр…');useEffect(()=>{let cancelled=false;let objectUrl='';const load=async()=>{try{const headers:Record<string,string>={};const key=localStorage.getItem('zmk_api_key')||'';const tgData=(window as any).Telegram?.WebApp?.initData||'';if(key)headers['X-API-Key']=key;if(tgData)headers['X-Telegram-Init-Data']=tgData;const response=await fetch(`/api/events/${event.id}/frame`,{headers,cache:'no-store'});if(!response.ok)throw new Error('Кадр события недоступен');objectUrl=URL.createObjectURL(await response.blob());if(!cancelled){setSrc(objectUrl);setError('')}}catch(e){if(!cancelled)setError(e instanceof Error?e.message:'Кадр события недоступен')}};void load();return()=>{cancelled=true;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[event.id]);return <div className="modal-backdrop"><div className="camera-modal event-evidence-modal"><div className="modal-head"><div><h2>Кадр события</h2><p>{labels[event.type]||event.type} · {event.camera_name||event.camera_id}</p></div><button onClick={close} aria-label="Закрыть"><X/></button></div>{src?<img src={src} alt={`Кадр события ${labels[event.type]||event.type}`}/>:<div className="event-evidence-loading">{error}</div>}<div className="event-evidence-meta"><span><b>Уверенность</b>{Math.round(event.confidence*100)}%</span><span><b>Время</b>{new Date(event.timestamp).toLocaleString('ru-RU')}</span><span><b>Объект</b>{event.person_id||'—'}</span><span><b>Решение</b>{event.review_status==='rejected'?'Не принято':event.review_status==='accepted'?'Принято':'Ожидает проверки'}</span></div>{event.note&&<p className="event-review-note"><b>Комментарий:</b> {event.note}</p>}<div className="modal-actions"><button onClick={()=>downloadFile(`/api/events/${event.id}/frame`,`zmk-event-${event.id}.jpg`).catch(()=>{})}><Download size={15}/> Скачать JPEG</button><button className="primary" onClick={close}>Закрыть</button></div></div></div>}
function CameraPreview({id,status,age,telemetryStale,lastError}:{id:string;status:string;age:number|null;telemetryStale?:boolean;lastError?:string}){
 const[src,setSrc]=useState('');const[live,setLive]=useState(false);const[streamFailed,setStreamFailed]=useState(false);const apiKey=localStorage.getItem('zmk_api_key')||'';
 useEffect(()=>{let cancelled=false;let current='';let fallbackTimer=0;const controller=new AbortController();const replace=(next:string)=>{if(cancelled){URL.revokeObjectURL(next);return}setSrc(old=>{if(old&&old!==next)URL.revokeObjectURL(old);return next});current=next};const snapshot=async()=>{try{const headers:Record<string,string>={};if(apiKey)headers['X-API-Key']=apiKey;const r=await fetch(`/api/cameras/${id}/snapshot?t=${Date.now()}`,{headers,signal:controller.signal});if(!r.ok)return;replace(URL.createObjectURL(await r.blob()))}catch{}};const marker=(data:Uint8Array,a:number,b:number,from=0)=>{for(let i=from;i<data.length-1;i++)if(data[i]===a&&data[i+1]===b)return i;return-1};const stream=async()=>{try{const headers:Record<string,string>={};if(apiKey)headers['X-API-Key']=apiKey;const r=await fetch(`/api/cameras/${id}/mjpeg`,{headers,signal:controller.signal,cache:'no-store'});if(!r.ok||!r.body)throw new Error('MJPEG unavailable');setLive(true);setStreamFailed(false);const reader=r.body.getReader();let buffer=new Uint8Array();while(!cancelled){const next=await reader.read();if(next.done)throw new Error('MJPEG closed');const joined=new Uint8Array(buffer.length+next.value.length);joined.set(buffer);joined.set(next.value,buffer.length);buffer=joined;while(true){const begin=marker(buffer,0xff,0xd8);if(begin<0){if(buffer.length>1)buffer=buffer.slice(-1);break}const finish=marker(buffer,0xff,0xd9,begin+2);if(finish<0){if(begin>0)buffer=buffer.slice(begin);break}const frame=buffer.slice(begin,finish+2);buffer=buffer.slice(finish+2);replace(URL.createObjectURL(new Blob([frame],{type:'image/jpeg'})))}}}catch{if(!cancelled){setLive(false);setStreamFailed(true);void snapshot();fallbackTimer=window.setInterval(snapshot,3000)}}};void snapshot();void stream();return()=>{cancelled=true;controller.abort();if(fallbackTimer)clearInterval(fallbackTimer);if(current)URL.revokeObjectURL(current)}},[id,apiKey]);
 const ageText=age===null?null:(age<5?'только что':(age<60?`${age} сек назад`:`${Math.floor(age/60)} мин назад`));
 if(!src)return <div className="feed-empty">{telemetryStale?<><WifiOff size={20}/><span>Нет телеметрии</span><small>worker давно не подтверждал поток</small></>:status==='connecting'?<><RefreshCw className="spin" size={20}/><span>Подключение к потоку</span><small>{lastError||'worker открывает RTSP-камеру'}</small></>:status==='offline'||status==='error'||status==='unknown'?<><WifiOff size={20}/><span>Поток не подключён</span><small>{lastError|| (status==='unknown'?'нет данных о статусе':'RTSP недоступен')}</small></>:<><Camera size={20}/><span>Кадр не получен</span><small>{lastError||'Нет свежего снимка от inference worker'}</small></>}</div>;
 return <><img className="camera-snapshot" src={src} alt={live?'Прямой эфир камеры':'Последний кадр камеры'}/><em className="frame-age">{live?'● LIVE MJPEG':(streamFailed?'snapshot fallback':ageText||'кадр')}</em></>
}
function Cameras({cams,changed}:{cams:Cam[],changed:()=>Promise<void>}){
 const[editing,setEditing]=useState<Cam|null|undefined>(undefined);const[selectionMode,setSelectionMode]=useState(false);const[selectedIds,setSelectedIds]=useState<string[]>([]);const[bulkConfirm,setBulkConfirm]=useState(false);const[form,setForm]=useState({name:'',zone:'',description:'',rtsp_url:'',fps_limit:'30',enabled:true});const[busy,setBusy]=useState(false);const[diag,setDiag]=useState<Record<string,string>>({});const[editRtsp,setEditRtsp]=useState(false);const[cardSize,setCardSize]=useState<'compact'|'normal'|'large'>(()=>{const saved=localStorage.getItem('zmk_camera_card_size');return saved==='compact'||saved==='large'?'compact'===saved?'compact':'large':'normal'});
 const chooseCardSize=(size:'compact'|'normal'|'large')=>{setCardSize(size);localStorage.setItem('zmk_camera_card_size',size)};const open=(cam?:Cam)=>{setEditing(cam||null);setEditRtsp(false);setForm(cam?{name:cam.name,zone:cam.zone,description:cam.description,rtsp_url:'',fps_limit:String(cam.fps_limit),enabled:!!cam.enabled}:{name:'',zone:'',description:'',rtsp_url:'',fps_limit:'30',enabled:true})};
 const save=async()=>{setBusy(true);try{const payload={...form,fps_limit:+form.fps_limit,rtsp_url:editing&&!editRtsp?null:form.rtsp_url};await api(editing?`/api/cameras/${editing.id}`:'/api/cameras',{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});setEditing(undefined);await changed()}catch(e){alert(e instanceof Error?e.message:'Ошибка сохранения камеры')}finally{setBusy(false)}};
 const diagnose=async(cam:Cam)=>{setDiag(v=>({...v,[cam.id]:'Проверка TCP-доступности…'}));try{const r=await api<any>(`/api/cameras/${cam.id}/diagnostics`,{method:'POST'});setDiag(v=>({...v,[cam.id]:r.reachable?`TCP доступен · ${r.latency_ms} мс${r.last_error?` · worker: ${r.last_error}`:''}`:r.last_error||r.message}))}catch(e){setDiag(v=>({...v,[cam.id]:'Ошибка диагностики'}))}};
 const restart=async(cam:Cam)=>{setDiag(v=>({...v,[cam.id]:'Запрошен перезапуск RTSP…'}));try{await api(`/api/cameras/${cam.id}/restart`,{method:'POST'});await changed();setDiag(v=>({...v,[cam.id]:'Worker переподключит камеру в течение нескольких секунд'}))}catch(e){setDiag(v=>({...v,[cam.id]:e instanceof Error?e.message:'Не удалось перезапустить камеру'}))}};const fullscreen=(cam:Cam)=>{const target=document.getElementById(`camera-feed-${cam.id}`);if(!target)return;if(document.fullscreenElement===target){void document.exitFullscreen()}else{void target.requestFullscreen().catch(()=>{})}};
 const toggleSelected=(id:string)=>setSelectedIds(ids=>ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]);const stopSelecting=()=>{setSelectionMode(false);setSelectedIds([]);setBulkConfirm(false)};const deleteSelected=async()=>{if(!selectedIds.length)return;setBusy(true);try{for(const id of selectedIds)await api(`/api/cameras/${id}?delete_events=true`,{method:'DELETE'});stopSelecting();await changed()}catch(e){alert(e instanceof Error?e.message:'Не удалось удалить выбранные камеры')}finally{setBusy(false)}};
 return <><div className="page-actions"><div><h3>Камеры</h3><p>{selectionMode?'Выберите карточки камер для удаления':'RTSP URL скрываются после сохранения; после включения AI-модели рамки человека и каски рисуются прямо на live-превью'}</p></div><div className="camera-page-tools">{!selectionMode?<><div className="camera-size-control" aria-label="Размер карточек">{(['compact','normal','large'] as const).map(size=><button key={size} className={cardSize===size?'active':''} onClick={()=>chooseCardSize(size)}>{size==='compact'?'Компакт':size==='normal'?'Обычные':'Крупные'}</button>)}</div><button onClick={()=>setSelectionMode(true)}><Trash2 size={15}/> Удалить камеры</button><button onClick={()=>open()}><Plus size={16}/> Добавить камеру</button></>:<div className="bulk-delete-tools"><b>Выбрано: {selectedIds.length}</b><button onClick={stopSelecting}>Отмена</button><button className="danger" disabled={!selectedIds.length} onClick={()=>setBulkConfirm(true)}><Trash2 size={15}/> Удалить выбранные</button></div>}</div></div>{cams.length===0?<div className="panel empty-state"><Camera size={36}/><h3>Камер пока нет</h3><p>Добавьте RTSP-камеру или заполните RTSP_CAM_01 в .env.</p><button onClick={()=>open()}><Plus size={15}/> Добавить</button></div>:<div className={`cards size-${cardSize} ${selectionMode?'selecting':''}`}>{cams.map(c=>{const selected=selectedIds.includes(c.id);return <article className={`camera-card ${selectionMode?'selection-mode':''} ${selected?'selected':''}`} key={c.id} onClick={selectionMode?()=>toggleSelected(c.id):undefined}><div id={`camera-feed-${c.id}`} className={`feed ${!selectionMode?'clickable':'selection-feed'}`} role="button" tabIndex={0} aria-pressed={selectionMode?selected:undefined} aria-label={selectionMode?`Выбрать камеру ${c.name}`:`Открыть камеру ${c.name} на весь экран`} onClick={e=>{if(selectionMode){e.stopPropagation();toggleSelected(c.id)}else fullscreen(c)}} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectionMode?toggleSelected(c.id):fullscreen(c)}}}><CameraPreview id={c.id} status={c.status} age={c.snapshot_age_seconds??null} telemetryStale={c.telemetry_stale} lastError={c.last_error}/>{selectionMode&&<span className={`selection-check ${selected?'checked':''}`}>{selected&&<Check size={16}/>}</span>}<span className={`live ${c.status}`}>{c.status==='online'?'● LIVE':(STATUS_LABEL[c.status]||c.status).toUpperCase()}</span><b>{c.id}</b></div><div className="camera-info"><div><h3>{c.name}</h3><p>{c.zone}</p></div><span className={`tag ${c.status}`}>{STATUS_LABEL[c.status]||c.status}</span></div><p className="camera-desc">{c.description||'Описание не задано'}</p><div className="camera-stats"><span title="Фактически декодированные кадры в секунду / заданный лимит">FPS <b>{c.fps.toFixed(1)}</b><small>/ лимит {c.fps_limit}</small></span><span>Latency <b>{c.latency_ms||'—'} ms</b></span><span>RTSP <b>{c.configured?'SET':'—'}</b></span></div>{c.last_error&&<div className="diag-result"><b>Причина:</b> {c.last_error}</div>}{diag[c.id]&&<div className="diag-result">{diag[c.id]}</div>}{!selectionMode?<div className="camera-actions"><button onClick={()=>diagnose(c)}><Stethoscope size={14}/> Проверить</button><button onClick={()=>restart(c)} disabled={!c.enabled}><RefreshCw size={14}/> Перезапустить</button><button onClick={()=>downloadFile(`/api/cameras/${c.id}/snapshot`,`zmk-${c.id}-${Date.now()}.jpg`).catch(()=>alert('Кадр пока не получен'))}><Download size={14}/> Снимок</button><button onClick={()=>open(c)}><Pencil size={14}/> Изменить</button></div>:<div className="selection-card-note">{selected?'Выбрана для удаления':'Нажмите на карточку для выбора'}</div>}</article>})}</div>}{bulkConfirm&&<div className="modal-backdrop"><div className="camera-modal"><div className="modal-head"><h2>Удалить выбранные камеры?</h2><button onClick={()=>setBulkConfirm(false)}><X/></button></div><p>Будет удалено камер: {selectedIds.length}. Связанные события, snapshots и live frames также будут удалены. Это действие нельзя отменить.</p><div className="modal-actions"><button disabled={busy} onClick={()=>setBulkConfirm(false)}>Отмена</button><button className="danger" disabled={busy} onClick={deleteSelected}><Trash2 size={15}/> {busy?'Удаляю…':'Удалить выбранные'}</button></div></div></div>}{editing!==undefined&&<div className="modal-backdrop"><div className="camera-modal"><div className="modal-head"><h2>{editing?'Изменить камеру':'Новая камера'}</h2><button onClick={()=>setEditing(undefined)}><X/></button></div><label>Название<input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} placeholder="Камера цеха №1"/></label><label>Зона<input value={form.zone} onChange={e=>setForm({...form,zone:e.target.value})} placeholder="Цех №1"/></label><label>Описание<textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Что контролирует камера"/></label>{editing?<label className="rtsp-edit">RTSP URL<em className="rtsp-note"><Check size={13}/> Ссылка уже настроена и скрыта. Чтобы заменить её — включите «Ввести новую ссылку» ниже.</em></label>:<label>RTSP URL<input type="password" value={form.rtsp_url} onChange={e=>setForm({...form,rtsp_url:e.target.value})} placeholder="rtsp://user:password@host/stream"/></label>}{editing&&!editRtsp&&<label className="check"><input type="checkbox" checked={false} onChange={e=>{setEditRtsp(e.target.checked);if(e.target.checked)setForm({...form,rtsp_url:''})}}/> Ввести новую ссылку</label>}{editing&&editRtsp&&<label>Новая RTSP URL<input type="password" value={form.rtsp_url} onChange={e=>setForm({...form,rtsp_url:e.target.value})} placeholder="rtsp://user:password@host/stream"/></label>}<label>Ограничение FPS <b className="fps-value">{form.fps_limit} FPS</b><input className="fps-slider" type="range" min="0.1" max="60" step="1" value={form.fps_limit} onChange={e=>setForm({...form,fps_limit:e.target.value})}/><small>До 60 FPS. Фактическое значение зависит от камеры, NVR, сети и декодера; AI не ограничивает live-превью.</small><div className="fps-presets">{[25,30,50,60].map(fps=><button type="button" key={fps} className={+form.fps_limit===fps?'active':''} onClick={()=>setForm({...form,fps_limit:String(fps)})}>{fps} FPS</button>)}</div></label><label className="check"><input type="checkbox" checked={form.enabled} onChange={e=>setForm({...form,enabled:e.target.checked})}/> Аналитика включена</label><div className="modal-actions"><button onClick={()=>setEditing(undefined)}>Отмена</button><button className="primary" disabled={busy||form.name.length<2} onClick={save}><Save size={15}/> Сохранить</button></div></div></div>}</>
}
function Events({events,ack,reject,ackMany,rejectMany}:{events:Event[],ack:(id:number)=>void,reject:(id:number,note:string)=>Promise<void>,ackMany:(ids:number[],note:string)=>Promise<number[]>,rejectMany:(ids:number[],note:string)=>Promise<number[]>}){type ReviewMode='accept'|'reject';const[filtersOpen,setFiltersOpen]=useState(false);const[severity,setSeverity]=useState('all');const[eventType,setEventType]=useState('all');const[reviewState,setReviewState]=useState('all');const[cameraId,setCameraId]=useState('all');const[term,setTerm]=useState('');const[evidence,setEvidence]=useState<Event|null>(null);const[selectionMode,setSelectionMode]=useState(false);const[selectedIds,setSelectedIds]=useState<number[]>([]);const[reviewDialog,setReviewDialog]=useState<{mode:ReviewMode,ids:number[]}|null>(null);const[reviewNote,setReviewNote]=useState('');const[reviewBusy,setReviewBusy]=useState(false);const[reviewError,setReviewError]=useState('');const cameraOptions=Array.from(new Map(events.map(event=>[event.camera_id,{id:event.camera_id,name:event.camera_name||event.camera_id,zone:event.zone||''}])).values());const statusOf=(event:Event)=>event.review_status||(event.acknowledged?'accepted':'pending');const shown=events.filter(event=>{const haystack=`${labels[event.type]||event.type} ${event.camera_name||event.camera_id} ${event.zone||''} ${event.person_id||''} ${event.note||''}`.toLocaleLowerCase('ru-RU');return (severity==='all'||event.severity===severity)&&(eventType==='all'||event.type===eventType)&&(cameraId==='all'||event.camera_id===cameraId)&&(reviewState==='all'||statusOf(event)===reviewState)&&(!term.trim()||haystack.includes(term.trim().toLocaleLowerCase('ru-RU')))});const reset=()=>{setSeverity('all');setEventType('all');setReviewState('all');setCameraId('all');setTerm('')};const toggle=(id:number)=>setSelectedIds(ids=>ids.includes(id)?ids.filter(item=>item!==id):[...ids,id]);const stopSelecting=()=>{setSelectionMode(false);setSelectedIds([]);setReviewDialog(null);setReviewError('');setReviewNote('')};const selectVisible=()=>setSelectedIds(ids=>Array.from(new Set([...ids,...shown.map(event=>event.id)])));const exportCsv=()=>{const params=new URLSearchParams();if(severity!=='all')params.set('severity',severity);if(eventType!=='all')params.set('event_type',eventType);if(cameraId!=='all')params.set('camera_id',cameraId);if(reviewState!=='all')params.set('review_status',reviewState);if(term.trim())params.set('q',term.trim());void downloadFile(`/api/reports/events.csv?${params.toString()}`,'zmk-events-filtered.csv').catch(()=>{})};const openReview=(mode:ReviewMode,ids:number[],note='')=>{setReviewError('');setReviewNote(note);setReviewDialog({mode,ids})};const submitReview=async()=>{if(!reviewDialog?.ids.length)return;setReviewBusy(true);setReviewError('');try{if(reviewDialog.mode==='accept')await ackMany(reviewDialog.ids,reviewNote);else await rejectMany(reviewDialog.ids,reviewNote);if(selectionMode)stopSelecting();else{setReviewDialog(null);setReviewNote('')}}catch(e){setReviewError(e instanceof Error?e.message:'Не удалось сохранить решение')}finally{setReviewBusy(false)}};return <><article className="panel full event-panel"><div className="toolbar"><div><h3>Журнал событий</h3><p>{selectionMode?`Выбрано: ${selectedIds.length}`:`Показано ${shown.length} из ${events.length} последних детекций`}</p></div>{!selectionMode?<div><button className={filtersOpen?'active-filter':''} onClick={()=>setFiltersOpen(v=>!v)}><SlidersHorizontal size={16}/> Фильтры</button><button onClick={()=>setSelectionMode(true)}><Check size={16}/> Выбрать события</button><button onClick={exportCsv}><Download size={16}/> Экспорт CSV</button></div>:<div className="bulk-event-tools"><button onClick={selectVisible}><Check size={15}/> Выбрать видимые</button><button onClick={stopSelecting}>Отмена</button><button className="primary" disabled={!selectedIds.length} onClick={()=>openReview('accept',selectedIds)}><Check size={15}/> Принять</button><button className="danger" disabled={!selectedIds.length} onClick={()=>openReview('reject',selectedIds)}><X size={15}/> Не принять</button></div>}</div>{filtersOpen&&<div className="event-filters"><label><span>Поиск</span><input value={term} onChange={e=>setTerm(e.target.value)} placeholder="Камера, зона, объект"/></label><label><span>Камера</span><select value={cameraId} onChange={e=>setCameraId(e.target.value)}><option value="all">Все камеры</option>{cameraOptions.map(camera=><option value={camera.id} key={camera.id}>{camera.name}{camera.zone?` · ${camera.zone}`:''}</option>)}</select></label><label><span>Уровень</span><select value={severity} onChange={e=>setSeverity(e.target.value)}><option value="all">Все</option><option value="critical">Критический</option><option value="high">Высокий</option><option value="medium">Средний</option><option value="low">Низкий</option></select></label><label><span>Тип</span><select value={eventType} onChange={e=>setEventType(e.target.value)}><option value="all">Все типы</option>{Object.entries(labels).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label><span>Решение</span><select value={reviewState} onChange={e=>setReviewState(e.target.value)}><option value="all">Все</option><option value="pending">Требуют внимания</option><option value="accepted">Приняты</option><option value="rejected">Не приняты</option></select></label><button onClick={reset}>Сбросить</button></div>}{shown.length?<EventsTable events={shown} ack={ack} onReject={event=>openReview('reject',[event.id],event.note||'')} openEvidence={setEvidence} selectionMode={selectionMode} selectedIds={selectedIds} onToggle={toggle}/>:<div className="empty-state"><Search size={32}/><h3>События не найдены</h3><p>Измените фильтры или дождитесь новой детекции.</p><button onClick={reset}>Сбросить фильтры</button></div>}</article>{evidence&&<EventEvidenceModal event={evidence} close={()=>setEvidence(null)}/>} {reviewDialog&&<div className="modal-backdrop"><div className={`camera-modal bulk-ack-modal ${reviewDialog.mode==='reject'?'reject-review-modal':''}`}><div className="modal-head"><div><h2>{reviewDialog.mode==='reject'?'Не принять события':'Принять выбранные события'}</h2><p>{reviewDialog.ids.length} событий будут отмечены как {reviewDialog.mode==='reject'?'не принятые':'проверенные'}.</p></div><button disabled={reviewBusy} onClick={()=>setReviewDialog(null)} aria-label="Закрыть"><X/></button></div><label>Комментарий оператора<textarea value={reviewNote} onChange={e=>setReviewNote(e.target.value)} placeholder={reviewDialog.mode==='reject'?'Например: ложное срабатывание, ремонтная зона':'Например: проверено сменным мастером'}/><small>{reviewDialog.mode==='reject'?'Причина помогает улучшать датасет и отделять ложные срабатывания.':'Комментарий попадёт в журнал каждого нового принятого события.'}</small></label>{reviewError&&<div className="capture-error">{reviewError}</div>}<div className="modal-actions"><button disabled={reviewBusy} onClick={()=>setReviewDialog(null)}>Отмена</button><button className={reviewDialog.mode==='reject'?'danger':'primary'} disabled={reviewBusy} onClick={submitReview}>{reviewDialog.mode==='reject'?<><X size={15}/>{reviewBusy?'Сохраняю…':'Не принять'}</>:<><Check size={15}/>{reviewBusy?'Сохраняю…':'Принять выбранные'}</>}</button></div></div></div>}</>}
function Models({cams}:{cams:Cam[]}){
 type ModelPage='registry'|'training'|'datasets';
 const[page,setPage]=useState<ModelPage>('registry');
 const[models,setModels]=useState<Model[]>([]);const[jobs,setJobs]=useState<Job[]>([]);const[captureJobs,setCaptureJobs]=useState<CaptureJob[]>([]);const[caps,setCaps]=useState<Capability|null>(null);const[cam,setCam]=useState('');const[source,setSource]=useState<'camera'|'dataset'>('camera');const[datasets,setDatasets]=useState<Dataset[]>([]);const[dsName,setDsName]=useState('');const[dsBusy,setDsBusy]=useState(false);const[prevBusy,setPrevBusy]=useState(false);const[preview,setPreview]=useState<{count:number,items:{source:string,label:string,image:string}[]}|null>(null);const[trainForm,setTrainForm]=useState({image_count:200,epochs:30,batch:8,imgsz:640,patience:20,confidence:.35,val_split:.2,capture_fps:2});const[busy,setBusy]=useState(false);const[captureBusy,setCaptureBusy]=useState(false);const[captureError,setCaptureError]=useState('');const[captureForm,setCaptureForm]=useState({name:'',image_count:100,capture_fps:2});const[datasetToDelete,setDatasetToDelete]=useState<Dataset|null>(null);const[datasetDeleteBusy,setDatasetDeleteBusy]=useState(false);const[datasetDeleteError,setDatasetDeleteError]=useState('');const[registering,setRegistering]=useState(false);const[modelForm,setModelForm]=useState({name:'',format:'ONNX',precision:'',recall:'',source:'external',artifact_uri:'',checksum:''});const[presets,setPresets]=useState<any[]>([]);const[dlBusy,setDlBusy]=useState<string|null>(null);
 const load=async()=>{const[m,j,c,d,cap]=await Promise.all([api<Model[]>('/api/models'),api<Job[]>('/api/training/jobs'),api<Capability>('/api/capabilities'),api<Dataset[]>('/api/datasets'),api<CaptureJob[]>('/api/datasets/capture/jobs')]);setModels(m);setJobs(j);setCaptureJobs(cap);setCaps(c);setDatasets(d);if(!cam&&cams.length)setCam(cams.find(x=>x.status==='online')?.id||cams[0].id);if(!dsName&&d.length)setDsName(d[0].name)};
 useEffect(()=>{load();const timer=setInterval(load,5000);return()=>clearInterval(timer)},[cams.length]);
 const onlineCameras=cams.filter(c=>c.status==='online');
 const activate=async(name:string)=>{setBusy(true);try{await api(`/api/models/${encodeURIComponent(name)}/activate`,{method:'POST'});await load()}catch(e){alert(e instanceof Error?e.message:'Ошибка переключения модели')}finally{setBusy(false)}};
 const activatePpeTrial=async(model:Model)=>{setBusy(true);try{await api(`/api/models/${encodeURIComponent(model.name)}/activate-trial`,{method:'POST'});await load()}catch(e){alert(e instanceof Error?e.message:'Не удалось включить PPE-тест')}finally{setBusy(false)}};
 const deactivatePpeTrial=async(model:Model)=>{setBusy(true);try{await api(`/api/models/${encodeURIComponent(model.name)}/deactivate-trial`,{method:'POST'});await load()}catch(e){alert(e instanceof Error?e.message:'Не удалось остановить PPE-тест')}finally{setBusy(false)}};
 const register=async()=>{setBusy(true);try{await api('/api/models',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...modelForm,precision:+modelForm.precision,recall:+modelForm.recall})});setRegistering(false);await load()}catch(e){alert(e instanceof Error?e.message:'Ошибка регистрации модели')}finally{setBusy(false)}};
 const removeModel=async(model:Model)=>{if(!confirm(`Удалить модель «${model.name}»?`))return;setBusy(true);try{await api(`/api/models/${encodeURIComponent(model.name)}`,{method:'DELETE'});await load()}catch(e){alert(e instanceof Error?e.message:'Не удалось удалить модель')}finally{setBusy(false)}};
 const openRegistry=async()=>{setRegistering(true);try{const result=await api<{presets:any[]}>('/api/models/presets');setPresets(result.presets)}catch{setPresets([])}};
 const downloadPreset=async(id:string)=>{setDlBusy(id);try{await api(`/api/models/presets/${id}/download`,{method:'POST'});await load();const result=await api<{presets:any[]}>('/api/models/presets');setPresets(result.presets)}catch(e){alert(e instanceof Error?e.message:'Не удалось скачать модель')}finally{setDlBusy(null)}};
 const startTraining=async()=>{setBusy(true);try{const payload=source==='dataset'?{camera_id:cam,source:'dataset',dataset_name:dsName,...trainForm}:{camera_id:cam,source:'camera',...trainForm};await api('/api/training/jobs',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});await load()}catch(e){alert(e instanceof Error?e.message:'Ошибка запуска обучения')}finally{setBusy(false)}};
 const cancelTraining=async(id:number)=>{try{await api(`/api/training/jobs/${id}/cancel`,{method:'POST'});await load()}catch(e){alert(e instanceof Error?e.message:'Ошибка отмены обучения')}};
 const startCapture=async()=>{if(!cam||!captureForm.name.trim())return;setCaptureBusy(true);setCaptureError('');try{const result=await api<CaptureJob>('/api/datasets/capture',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({camera_id:cam,name:captureForm.name,image_count:Math.round(captureForm.image_count),capture_fps:captureForm.capture_fps})});setCaptureForm(v=>({...v,name:result.name}));await load()}catch(e){setCaptureError(e instanceof Error?e.message:'Не удалось начать сбор датасета')}finally{setCaptureBusy(false)}};
 const cancelCapture=async(id:number)=>{try{await api(`/api/datasets/capture/jobs/${id}/cancel`,{method:'POST'});await load()}catch(e){alert(e instanceof Error?e.message:'Не удалось отменить сбор')}};
 const uploadDataset=async(file:File)=>{setDsBusy(true);try{const key=localStorage.getItem('zmk_api_key')||'';const headers:Record<string,string>={'Content-Type':'application/zip'};if(key)headers['X-API-Key']=key;const name=file.name.toLowerCase().endsWith('.zip')?file.name.slice(0,-4):file.name;const response=await fetch(`/api/datasets?name=${encodeURIComponent(name)}`,{method:'POST',headers,body:file});if(!response.ok)throw new Error(await response.text());await load()}catch(e){alert(e instanceof Error?e.message:'Ошибка загрузки датасета')}finally{setDsBusy(false)}};
 const requestDatasetDelete=(dataset:Dataset)=>{if(datasetDeleteBusy)return;setDatasetDeleteError('');setDatasetToDelete(dataset)};const removeDataset=async()=>{const dataset=datasetToDelete;if(!dataset)return;setDatasetDeleteBusy(true);setDatasetDeleteError('');try{await api(`/api/datasets/${dataset.id}`,{method:'DELETE'});const remaining=datasets.filter(item=>item.id!==dataset.id);setDatasets(remaining);if(dsName===dataset.name)setDsName(remaining[0]?.name||'');setDatasetToDelete(null);void load().catch(()=>{})}catch(e){const raw=e instanceof Error?e.message:'Не удалось удалить датасет';try{const body=JSON.parse(raw);setDatasetDeleteError(typeof body.detail==='string'?body.detail:raw)}catch{setDatasetDeleteError(raw)}}finally{setDatasetDeleteBusy(false)}};
 const runPreview=async(name:string)=>{setPrevBusy(true);try{setDsName(name);const result=await api<{count:number,items:{source:string,label:string,image:string}[]}>(`/api/datasets/${encodeURIComponent(name)}/preview`,{method:'POST',headers:{'Content-Type':'application/json'},body:'{"limit":6}'});setPreview(result)}catch(e){alert(e instanceof Error?e.message:'Предпросмотр недоступен')}finally{setPrevBusy(false)}};
 const trainSetting=(key:keyof typeof trainForm,label:string,hint:string,min:number,max:number,step=1)=><label className="trainer-setting" key={key}><span><b>{label}</b><small>{hint}</small></span><input type="number" min={min} max={max} step={step} value={trainForm[key]} onChange={e=>setTrainForm({...trainForm,[key]:+e.target.value})}/></label>;
 const useDataset=(name:string)=>{setSource('dataset');setDsName(name);setPage('training')};
 return <><div className="page-actions"><div><h3>Модели и датасеты</h3><p>Три шага: кадры → датасет → обучение модели</p></div><button onClick={openRegistry}><Plus size={15}/> Зарегистрировать модель</button></div><div className="model-tabs">{([['registry','Модели',Cpu],['training','Обучение',BrainCircuit],['datasets','Датасеты',Database]] as const).map(([id,label,Icon])=><button key={id} className={page===id?'active':''} onClick={()=>setPage(id)}><Icon size={15}/>{label}</button>)}</div>
 {page==='registry'&&<><section className="model-help"><Cpu size={20}/><span><b>Шаг 1. Модель.</b><small>Зарегистрируйте готовый артефакт или скачайте preset. Для событий безопасности модель нужно дообучить на своих кадрах.</small></span></section>{models.length===0?<div className="panel empty-state"><Cpu size={36}/><h3>Модели не зарегистрированы</h3><p>Добавьте ONNX, TensorRT или PyTorch артефакт.</p><button onClick={openRegistry}>Добавить модель</button></div>:<div className="model-grid">{models.map(model=>{const validated=model.precision!==null&&model.recall!==null;return <article className={`panel model ${model.active?'active-model':''}`} key={model.name}>{model.active&&<span>{model.trial_mode?'PPE-ТЕСТ':'АКТИВНА'}</span>}<Cpu size={32}/><h2>{model.name}</h2><p>{model.format} • {model.source}</p>{model.trial_eligible&&<p className="ppe-trial-note"><ShieldAlert size={14}/><span>Стартовая PPE-модель: распознаёт человека, каску и «без каски». Порог события задаётся в «Настройки → Каска». Это тестовый режим — проверьте её на своих камерах до промышленного применения.</span></p>}<div><b>{model.precision===null?'—':`${model.precision}%`}<small>Precision</small></b><b>{model.recall===null?'—':`${model.recall}%`}<small>Recall</small></b><b>{model.status}<small>Статус</small></b></div>{model.trial_eligible&&!model.active?<button className="model-trial" disabled={busy} onClick={()=>activatePpeTrial(model)}><Play size={16}/> Включить PPE-тест</button>:<button disabled={model.active||busy||!validated} onClick={()=>activate(model.name)}>{model.active?<><Check size={16}/> Используется</>:validated?<>Сделать активной</>:<>Нужна валидация</>}</button>}{model.active&&model.trial_eligible&&<button className="model-trial-stop" disabled={busy} onClick={()=>deactivatePpeTrial(model)}><X size={14}/> Остановить PPE-тест</button>}<button className="model-del" disabled={model.active||busy} onClick={()=>removeModel(model)}><Trash2 size={14}/> Удалить</button></article>})}</div>}</>}
 {page==='training'&&<article className="panel trainer"><div className="trainer-head"><div className="train-icon"><BrainCircuit size={25}/></div><div><h2>Шаг 3. Обучение</h2><p>{caps?.training_worker?(caps?.training?.gpu?'Training worker подключён · GPU':'Training worker подключён · CPU fallback'):'Training worker не отвечает — проверьте контейнер training-worker'}</p></div></div>{!caps?.training_worker?<div className="notice"><AlertTriangle size={16}/><span>Training worker должен стартовать вместе с проектом. Проверьте контейнер и повторите запуск.</span></div>:<><div className="trainer-toolbar"><div className="segmented train-mode"><button className={source==='camera'?'active':''} onClick={()=>setSource('camera')}>Кадры с камеры</button><button className={source==='dataset'?'active':''} onClick={()=>setSource('dataset')}>Готовый датасет</button></div>{source==='camera'?<label className="inline-field"><span>Камера</span><select value={cam} onChange={e=>setCam(e.target.value)}><option value="">Выберите камеру</option>{onlineCameras.map(c=><option key={c.id} value={c.id}>{c.name} · {c.zone}</option>)}</select></label>:<label className="inline-field"><span>Датасет</span><select value={dsName} onChange={e=>setDsName(e.target.value)}><option value="">Выберите датасет</option>{datasets.map(d=><option key={d.id} value={d.name}>{d.name} · {KIND_LABEL[d.kind||'yolo']} · {(d.kind==='videos'?d.media_count:d.image_count)} кадров</option>)}</select></label>}<button className="trainer-start" disabled={busy||(source==='camera'?!cam:!dsName)} onClick={startTraining}><Play size={15}/> Запустить обучение</button></div><div className="trainer-settings">{source==='camera'&&trainSetting('image_count','Количество кадров','Сколько кадров взять для обучения. Больше кадров — выше разнообразие и дольше сбор.',20,5000,10)}{trainSetting('epochs','Эпохи','Количество проходов обучения. Начните с 20–30.',1,300)}{trainSetting('batch','Batch size','Кадров в одном шаге. Уменьшите, если не хватает памяти.',1,128)}{trainSetting('imgsz','Размер изображения','Сторона кадра для YOLO. Больше размер — выше нагрузка.',320,1920,32)}{trainSetting('patience','Patience','Остановить обучение после стольких эпох без улучшения.',0,100)}{trainSetting('confidence','Порог псевдоразметки','Минимальная уверенность базовой модели для автоматической разметки.',.05,.95,.05)}{trainSetting('val_split','Доля валидации','Часть кадров для проверки качества, не участвует в обучении.',.1,.4,.05)}{source==='camera'&&trainSetting('capture_fps','FPS захвата','Как часто брать кадры камеры именно для обучения.',.1,20,.1)}</div></>}{jobs.length>0&&<div className="jobs training-jobs">{jobs.map(job=><div className="job" key={job.id}><span><b>{job.target_name}</b><small>{job.camera_id||job.dataset_name||'—'}</small></span><span><b>{job.image_count} кадров</b><small>{job.epochs} эпох</small></span><span><b>{job.stage}</b><small>{job.error||new Date(job.created_at).toLocaleString('ru-RU')}</small></span><span><div className="progress"><i style={{width:`${job.progress}%`}}/></div><small>{job.progress}%</small></span><span className={`jobstatus ${job.status}`}>{job.status}{['queued','running'].includes(job.status)&&<button onClick={()=>cancelTraining(job.id)}>Отменить</button>}</span></div>)}</div>}</article>}
 {page==='datasets'&&<><article className="panel dataset-capture-panel"><div className="dataset-panel-head"><Camera size={24}/><span><h2>Шаг 2. Собрать датасет с камеры</h2><p>Кадры сохраняются из текущего live MJPEG-потока. Обучение запускается отдельно на вкладке «Обучение».</p></span></div><div className="capture-form"><label><span><b>Камера</b><small>Источник live-кадров. Камера должна быть online.</small></span><select value={cam} onChange={e=>setCam(e.target.value)}><option value="">Выберите камеру</option>{onlineCameras.map(c=><option key={c.id} value={c.id}>{c.name} · {c.zone}</option>)}</select></label><label><span><b>Имя датасета</b><small>Уникальное имя. Оно будет видно в списке датасетов.</small></span><input value={captureForm.name} onChange={e=>setCaptureForm({...captureForm,name:e.target.value})} placeholder="camera-shift-01"/></label><label><span><b>Количество кадров: {captureForm.image_count}</b><small>20–1000 кадров. Больше кадров — больше данных и дольше сбор.</small></span><input type="range" min="20" max="1000" step="10" value={captureForm.image_count} onChange={e=>setCaptureForm({...captureForm,image_count:+e.target.value})}/></label><label><span><b>Частота сбора: {captureForm.capture_fps} FPS</b><small>1–2 FPS обычно достаточно. Не выше реального FPS камеры.</small></span><input type="range" min="0.1" max="20" step="0.1" value={captureForm.capture_fps} onChange={e=>setCaptureForm({...captureForm,capture_fps:+e.target.value})}/></label></div>{captureError&&<div className="capture-error">{captureError}</div>}<div className="dataset-panel-actions"><button className="primary" disabled={captureBusy||!cam||!captureForm.name.trim()} onClick={startCapture}><Camera size={15}/>{captureBusy?'Запускаю…':'Начать сбор кадров'}</button></div></article>{captureJobs.length>0&&<article className="panel capture-jobs-panel"><PanelTitle title="Сбор датасетов" sub="Текущие и последние задачи"/>{captureJobs.map(job=><div className="job" key={`capture-${job.id}`}><span><b>{job.name}</b><small>{job.camera_id}</small></span><span><b>{job.captured_count}/{job.target_count} кадров</b><small>{job.capture_fps} FPS</small></span><span><b>{job.stage}</b><small>{job.error||new Date(job.created_at).toLocaleString('ru-RU')}</small></span><span><div className="progress"><i style={{width:`${Math.min(100,job.captured_count/job.target_count*100)}%`}}/></div><small>{Math.round(Math.min(100,job.captured_count/job.target_count*100))}%</small></span><span className={`jobstatus ${job.status}`}>{job.status}{['queued','running'].includes(job.status)&&<button onClick={()=>cancelCapture(job.id)}>Отменить</button>}</span></div>)}</article>}<article className="panel dataset-upload-panel"><div className="dataset-panel-head"><Database size={24}/><span><h2>Загрузить готовый датасет</h2><p>ZIP с фото, видео или готовой YOLO-структурой.</p></span></div><div className="dataset-panel-actions"><label className="upload-btn"><input type="file" accept=".zip" hidden onChange={e=>{const file=e.target.files?.[0];if(file)uploadDataset(file);e.currentTarget.value=''}}/><Download size={14}/> {dsBusy?'Загрузка…':'Выбрать ZIP-архив'}</label></div></article><article className="panel datasets-list-panel"><PanelTitle title="Сохранённые датасеты" sub="Выберите один для обучения или проверки разметки"/>{datasets.length===0?<div className="empty">Датасетов пока нет. Соберите кадры с камеры или загрузите ZIP.</div>:<div className="dataset-items">{datasets.map(dataset=><div className="dataset-item" key={dataset.id}><span><b>{dataset.name}</b><small>{KIND_LABEL[dataset.kind||'yolo']} · {(dataset.kind==='videos'?dataset.media_count:dataset.image_count)} кадров{dataset.class_count?` · ${dataset.class_count} классов`:''}</small></span><div><button onClick={()=>useDataset(dataset.name)}><BrainCircuit size={14}/> Обучить</button><button className="preview-btn" disabled={prevBusy} onClick={()=>runPreview(dataset.name)}><Eye size={14}/> Проверить</button><button className="danger" title={`Удалить датасет ${dataset.name}`} aria-label={`Удалить датасет ${dataset.name}`} disabled={datasetDeleteBusy} onClick={()=>requestDatasetDelete(dataset)}><Trash2 size={14}/> Удалить</button></div></div>)}</div>}</article></>}
 {datasetToDelete&&<div className="modal-backdrop" role="presentation"><div className="camera-modal dataset-delete-modal" role="dialog" aria-modal="true" aria-labelledby="dataset-delete-title"><div className="modal-head"><h2 id="dataset-delete-title">Удалить датасет?</h2><button aria-label="Закрыть" disabled={datasetDeleteBusy} onClick={()=>{setDatasetDeleteError('');setDatasetToDelete(null)}}><X/></button></div><p>Будут удалены запись и все файлы датасета <b>«{datasetToDelete.name}»</b>. Это действие нельзя отменить.</p><p className="dataset-delete-hint">Если датасет используется запущенным обучением, сначала отмените задачу или дождитесь её завершения.</p>{datasetDeleteError&&<div className="capture-error" role="alert">{datasetDeleteError}</div>}<div className="modal-actions"><button disabled={datasetDeleteBusy} onClick={()=>{setDatasetDeleteError('');setDatasetToDelete(null)}}>Отмена</button><button className="danger" disabled={datasetDeleteBusy} onClick={removeDataset}><Trash2 size={15}/> {datasetDeleteBusy?'Удаляю…':'Удалить датасет'}</button></div></div></div>}
 {registering&&<div className="modal-backdrop"><div className="camera-modal model-register-modal"><div className="modal-head"><h2>Регистрация модели</h2><button onClick={()=>setRegistering(false)}><X/></button></div><label>Имя модели<input value={modelForm.name} onChange={e=>setModelForm({...modelForm,name:e.target.value})} placeholder="safety-v1"/><small>Уникальное короткое имя версии модели.</small></label><label>Формат<select value={modelForm.format} onChange={e=>setModelForm({...modelForm,format:e.target.value})}><option>ONNX</option><option>ONNX FP16</option><option>TensorRT</option><option>TensorRT FP16</option><option>PyTorch</option></select><small>Формат должен соответствовать файлу артефакта.</small></label><label>Artifact URI<input value={modelForm.artifact_uri} onChange={e=>setModelForm({...modelForm,artifact_uri:e.target.value})} placeholder="file:///models/model.onnx"/><small>Путь к файлу модели на сервере, например file:///models/model.onnx.</small></label><div className="form-row"><label>Precision, %<input type="number" min="0" max="100" value={modelForm.precision} onChange={e=>setModelForm({...modelForm,precision:e.target.value})}/><small>Точность на валидационном наборе.</small></label><label>Recall, %<input type="number" min="0" max="100" value={modelForm.recall} onChange={e=>setModelForm({...modelForm,recall:e.target.value})}/><small>Полнота обнаружения на валидации.</small></label></div><label>SHA-256 checksum<input value={modelForm.checksum} onChange={e=>setModelForm({...modelForm,checksum:e.target.value})}/><small>Необязательно, но защищает от подмены файла.</small></label><div className="modal-actions"><button onClick={()=>setRegistering(false)}>Отмена</button><button className="primary" disabled={busy||!modelForm.name||!modelForm.artifact_uri} onClick={register}><Save size={15}/> Сохранить</button></div><div className="preset-block"><div className="preset-head"><h3>Готовые модели</h3><p>Для каски выберите карточку PPE: стандартная COCO-модель видит человека, но не умеет распознавать защитную каску.</p></div><div className="preset-grid">{[...presets].sort((a,b)=>a.category==='safety'?-1:b.category==='safety'?1:0).map(pr=>{const mb=(pr.size_bytes/1024/1024).toFixed(1);const category=pr.category==='safety'?'PPE':pr.category==='starter'?'Старт':'Базовый';return <article className={`preset-card ${pr.downloaded?'done':''} ${pr.trial_activation?'ppe-preset':''}`} key={pr.id}><div className="preset-card-head"><b>{pr.name}</b><span className={`preset-cat ${pr.category}`}>{category}</span></div><p>{pr.description}</p>{pr.trial_activation&&<p className="preset-trial-hint">После скачивания появится отдельная кнопка «Включить PPE-тест». Сначала проверьте результат на своей камере.</p>}<div className="preset-meta"><span>{pr.classes} классов</span><span>{mb} МБ</span><span>{pr.downloaded?'в реестре':'не скачана'}</span></div><button className="preset-dl" disabled={!!dlBusy||pr.downloaded} onClick={()=>downloadPreset(pr.id)}><Download size={14}/> {pr.downloaded?'Скачано':dlBusy===pr.id?'Скачиваю…':pr.trial_activation?'Скачать PPE-модель':'Скачать'}</button></article>})}</div></div></div></div>}{preview&&<div className="modal-backdrop"><div className="camera-modal preview-modal"><div className="modal-head"><h2>Предпросмотр псевдоразметки</h2><button onClick={()=>setPreview(null)}><X/></button></div><p className="preview-sub">Как активная модель разметит первые кадры из «{dsName}» ({preview.count} шт.). Жёлтые рамки — найденные объекты.</p><div className="preview-grid">{preview.items.map((item,i)=><figure key={i}><img src={`data:image/jpeg;base64,${item.image}`} alt="Предпросмотр"/><figcaption>{item.source} · {item.label}</figcaption></figure>)}</div><div className="modal-actions"><button className="primary" onClick={()=>setPreview(null)}>Понятно</button></div></div></div>}</>}
function Diagnostics(){
 const[data,setData]=useState<any>(null);const[loading,setLoading]=useState(false);const[error,setError]=useState('');
 const run=async()=>{setLoading(true);setError('');try{setData(await api('/api/diagnostics'))}catch(e){setError(e instanceof Error?e.message:'Диагностика недоступна')}finally{setLoading(false)}};
 useEffect(()=>{run()},[]);
 const worker=data?.worker;
 return <><div className="page-actions"><div><h3>Диагностика</h3><p>RTSP, heartbeat worker и фактическое состояние камер</p></div><button onClick={run} disabled={loading}><RefreshCw className={loading?'spin':''} size={15}/> Запустить</button></div>{error&&<div className="api-error">{error}</div>}{data&&<><div className="admin-metrics"><Metric icon={Cpu} label="CPU" value={data.system.cpu} unit="%" accent="blue" delta="Фактическая загрузка"/><Metric icon={Database} label="RAM" value={data.system.ram} unit="%" accent="green" delta="Фактическое использование"/><Metric icon={Database} label="Диск" value={data.system.disk} unit="%" accent="amber" delta="Раздел базы данных"/><Metric icon={Cpu} label="GPU" value={data.system.gpu} unit="%" accent="red" delta={data.system.available?'NVIDIA обнаружена':'NVIDIA не обнаружена'}/></div><article className="panel diagnostic-panel"><PanelTitle title="Сервисы" sub={`Проверено ${new Date(data.generated_at).toLocaleString('ru-RU')}`}/><div className="service-grid">{data.system.services.map((x:any)=><div key={x.name}><span className={`service-dot ${x.status}`}/><b>{x.name}</b><small>{x.status}</small></div>)}</div><div className={`inference-banner ${worker?.connected?'ok':'warn'}`}>{worker?.connected?<><Activity size={16}/><span><b>Camera worker на связи</b> · {worker.status} · {worker.detail||'heartbeat получен'}.</span></>:<><AlertTriangle size={16}/><span><b>Нет heartbeat от camera worker.</b> Пересоберите профиль <code>docker compose --profile inference up -d --build</code>, затем посмотрите <code>docker compose --profile inference logs -f inference-worker</code>.</span></>}</div><PanelTitle title="Камеры" sub={`${data.cameras.length} настроено`}/>{data.cameras.length===0?<div className="empty">Добавьте камеры для проверки</div>:<div className="diag-list">{data.cameras.map((x:any)=><div key={x.camera_id}><span className={`service-dot ${x.reachable?'healthy':'error'}`}/><b>{x.name}</b><small>{x.last_error||x.message}<br/>worker: {x.camera_status||'unknown'} · кадр: {x.snapshot||'none'} · телеметрия: {x.telemetry_age_seconds??'—'} сек</small><em>{x.latency_ms===null?'—':`${x.latency_ms} мс`}</em></div>)}</div>}</article></>}</>
}
function Admin(){const[page,setPage]=useState('Система');const[logs,setLogs]=useState<Log[]>([]);const[summary,setSummary]=useState({WARNING:0,ERROR:0,CRITICAL:0});const[admin,setAdmin]=useState({users:0,audit24h:0,errors24h:0,training_running:0});const[hours,setHours]=useState(24);const[config,setConfig]=useState<Record<string,Record<string,string>>>({});const[users,setUsers]=useState<any[]>([]);const[saved,setSaved]=useState('');const load=async()=>{const[r,a,c,u]=await Promise.all([api<{summary:any,items:Log[]}>(`/api/reports/errors?hours=${hours}`),api<any>('/api/admin/summary'),api<any>('/api/admin/config'),api<any[]>('/api/admin/users')]);setLogs(r.items);setSummary(r.summary);setAdmin(a);setConfig(c);setUsers(u)};useEffect(()=>{load()},[hours]);const setVal=(group:string,key:string,value:string)=>setConfig(v=>({...v,[group]:{...v[group],[key]:value}}));const save=async(group:string)=>{try{await api('/api/admin/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({values:config[group]})});setSaved(group);setTimeout(()=>setSaved(''),1800)}catch(e){alert(`Настройки не сохранены: ${e instanceof Error?e.message:'проверьте значения'}`)}};const toggleUser=async(id:number)=>{try{await api(`/api/admin/users/${id}/toggle`,{method:'PATCH'});await load()}catch(e){alert('Нельзя отключить последнего администратора')}};const readJson=(key:string)=>{try{return JSON.parse(localStorage.getItem(key)||'{}')}catch{localStorage.removeItem(key);return {}}};
const downloadFile=async(url:string,name:string)=>{const key=localStorage.getItem('zmk_api_key')||'';const tgData=(window as any).Telegram?.WebApp?.initData||'';const headers:Record<string,string>={};if(key)headers['X-API-Key']=key;if(tgData)headers['X-Telegram-Init-Data']=tgData;const r=await fetch(url,{headers});if(!r.ok)throw new Error('Не удалось скачать файл');const blob=await r.blob();const href=URL.createObjectURL(blob);const a=document.createElement('a');a.href=href;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),1000)};
const labels:Record<string,string>={site_name:'Название площадки',timezone:'Часовой пояс',language:'Язык',retention_days:'Хранение событий, дней',inference_fps:'FPS на поток',inference_device:'Устройство инференса',batch_size:'Размер batch',nms_iou:'NMS IoU',helmet_conf:'Порог каски',vest_conf:'Порог жилета',phone_conf:'Порог телефона',smoking_conf:'Порог курения',restricted_zone_conf:'Порог опасной зоны',immobility_conf:'Порог неподвижности',min_model_precision:'Минимальный Precision, %',min_model_recall:'Минимальный Recall, %',event_cooldown_seconds:'Cooldown события, сек',archive_quality:'Качество JPEG, %',archive_clip_seconds:'Длина клипа, сек',minio_endpoint:'MinIO endpoint',minio_bucket:'S3 bucket',minio_secure:'TLS для MinIO',telegram_enabled:'Уведомления бота',telegram_chat_ids:'ID получателей Telegram (legacy)',critical_alerts:'Критические оповещения',webhook_enabled:'Webhook СКУД',webhook_url:'Webhook URL',webhook_timeout:'Timeout, сек',rtsp_reconnect_seconds:'Переподключение RTSP, сек'};
const hints:Record<string,string>={site_name:'Отображается в заголовке панели и уведомлений.',timezone:'Часовой пояс для времени событий и отчётов (например, Asia/Krasnoyarsk).',language:'Язык интерфейса (ru / en).',retention_days:'Сколько дней хранить события. Старые удаляются автоматически.',inference_fps:'Сколько кадров в секунду обрабатывает инференс по каждому потоку.',inference_device:'Устройство для YOLO: cuda:0 (GPU) или cpu. Требует перезапуска worker.',batch_size:'Размер пакета кадров на один прогон модели — выше на GPU.',nms_iou:'Non-Max Suppression IoU. Больше — меньше дублирующих рамок.',helmet_conf:'Минимальная уверенность, чтобы засчитать «нет каски» (0.5–0.95).',vest_conf:'Минимальная уверенность для «нет жилета».',phone_conf:'Минимальная уверенность для «телефон» (0.5–0.95).',smoking_conf:'Минимальная уверенность для «курение».',restricted_zone_conf:'Минимальная уверенность для «вход в опасную зону».',immobility_conf:'Минимальная уверенность для «неподвижность».',min_model_precision:'Активировать модель можно, только если Precision не ниже этого значения (%).',min_model_recall:'Активировать модель можно, только если Recall не ниже этого значения (%).',event_cooldown_seconds:'Секунд между одинаковыми событиями по одной камере/объекту — защита от спама.',archive_quality:'Качество сохраняемых JPEG снимков (10–100).',archive_clip_seconds:'Длительность сохраняемого видеоклипа вокруг события.',minio_endpoint:'Адрес S3/МиниО хранилища (host:port).',minio_bucket:'Имя бакета в хранилище.',minio_secure:'Использовать TLS (https) при подключении к хранилищу.',telegram_enabled:'Включить push-уведомления бота о событиях.',telegram_chat_ids:'Какие chat ID бота получают уведомления (устаревшее поле).',critical_alerts:'Присылать только критические события.',webhook_enabled:'Отправлять события на внешнюю СКУД/систему через webhook.',webhook_url:'URL приёмника webhook (только http/https).',webhook_timeout:'Таймаут отправки webhook в секундах.',rtsp_reconnect_seconds:'Через сколько секунд worker переподключает потерянный RTSP-поток.'};const renderGroup=(group:string,title:string,sub:string)=><article className="panel settings-card"><div className="settings-title"><div><h3>{title}</h3><p>{sub}</p></div><button onClick={()=>save(group)}>{saved===group?<><Check size={15}/> Сохранено</>:<>Сохранить</>}</button></div><div className="setting-grid">{Object.entries(config[group]||{}).map(([k,v])=><label key={k}><span>{labels[k]||k}<small>{k}</small><em className="setting-hint">{hints[k]||''}</em></span>{['true','false'].includes(v)?<button className={`switch ${v==='true'?'on':''}`} onClick={()=>setVal(group,k,v==='true'?'false':'true')}><i/></button>:<input value={v} onChange={e=>setVal(group,k,e.target.value)}/>}</label>)}</div></article>;
return <><div className="admin-metrics"><Metric icon={Users} label="Пользователи" value={admin.users} accent="blue" delta="RBAC: admin / operator / viewer"/><Metric icon={FileWarning} label="Ошибки за 24 ч" value={admin.errors24h} accent="red" delta="ERROR и CRITICAL"/><Metric icon={Database} label="Записи аудита" value={admin.audit24h} accent="green" delta="Все действия операторов"/><Metric icon={BrainCircuit} label="Обучение" value={admin.training_running} accent="amber" delta="Активные задачи"/></div><div className="admin-tabs">{['Система','AI-модель','Архив','Уведомления','Интеграции','Пользователи','Логи'].map(x=><button key={x} className={page===x?'active':''} onClick={()=>setPage(x)}>{x}</button>)}</div>{page==='Система'&&renderGroup('general','Общие настройки','Площадка, локализация и срок хранения')}{page==='AI-модель'&&renderGroup('inference','Контур AI Inference','GPU, производительность, NMS и пороги событий')}{page==='Архив'&&renderGroup('archive','Архив изображений и видео','Качество, длительность клипа и подключение MinIO')}{page==='Уведомления'&&renderGroup('notifications','Оповещения','Правила критических уведомлений выбранного мессенджера')}{page==='Интеграции'&&renderGroup('integration','Интеграции и RTSP','Webhook СКУД, таймауты и восстановление потоков')}{page==='Пользователи'&&<article className="panel users-panel"><div className="settings-title"><div><h3>Пользователи и роли</h3><p>Управление доступом admin / operator / viewer</p></div><button onClick={async()=>{const login=prompt('Логин нового пользователя');if(!login)return;await api('/api/admin/users',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:login,login,role:'viewer'})});await load()}}>+ Добавить</button></div><div className="user-list">{users.length===0?<div className="empty">Пользователи не созданы. Доступ к API управляется ключом.</div>:users.map(u=><div className="user-row" key={u.id}><div className="avatar">{u.name.slice(0,2).toUpperCase()}</div><span><b>{u.name}</b><small>@{u.login}</small></span><i className={`role ${u.role}`}>{u.role}</i><span className={`ustatus ${u.active?'on':''}`}>{u.active?'Активен':'Отключён'}</span><button onClick={()=>toggleUser(u.id)}>{u.active?'Отключить':'Включить'}</button></div>)}</div></article>}{page==='Логи'&&<article className="panel error-report"><div className="toolbar"><div><h3>Отчёт об ошибках и предупреждениях</h3><p>Структурированные логи сервисов за выбранный период</p></div><div><select value={hours} onChange={e=>setHours(+e.target.value)}><option value="1">1 час</option><option value="24">24 часа</option><option value="168">7 дней</option><option value="720">30 дней</option></select><button onClick={()=>downloadFile(`/api/reports/errors.csv?hours=${hours}`,'zmk-error-report.csv')}><Download size={15}/> CSV</button></div></div><div className="logsummary"><span className="warn"><b>{summary.WARNING}</b> WARNING</span><span className="err"><b>{summary.ERROR}</b> ERROR</span><span className="crit"><b>{summary.CRITICAL}</b> CRITICAL</span></div><div className="logtable"><div className="logrow lh"><span>Время</span><span>Уровень</span><span>Сервис</span><span>Камера</span><span>Сообщение</span></div>{logs.length===0?<div className="empty">Ошибок за период нет</div>:logs.map(l=><div className="logrow" key={l.id}><span>{new Date(l.timestamp).toLocaleString('ru-RU')}</span><span><i className={`level ${l.level.toLowerCase()}`}>{l.level}</i></span><span>{l.service}</span><span>{l.camera_id||'—'}</span><span>{l.message}</span></div>)}</div></article>}</>}
function Config(){const[vals,setVals]=useState<Record<string,string>>({helmet_conf:'0.85',vest_conf:'0.80',phone_conf:'0.78',smoking_conf:'0.80',restricted_zone_conf:'0.82',immobility_conf:'0.80'});const[saved,setSaved]=useState(false);useEffect(()=>{api<Record<string,string>>('/api/settings').then(x=>setVals(v=>({...v,...x}))).catch(e=>console.error('Settings load failed',e))},[]);const names:Record<string,string>={helmet_conf:'Каска',vest_conf:'Сигнальный жилет',phone_conf:'Использование телефона',smoking_conf:'Курение',restricted_zone_conf:'Опасная зона',immobility_conf:'Неподвижность'};
const descs:Record<string,string>={'helmet_conf':'Мин. уверенность, чтобы засчитать «нет каски» (0.5–0.95).','vest_conf':'Мин. уверенность для «нет сигнального жилета».','phone_conf':'Мин. уверенность для «использование телефона».','smoking_conf':'Мин. уверенность для «курение».','restricted_zone_conf':'Мин. уверенность для «вход в опасную зону».','immobility_conf':'Мин. уверенность для «неподвижность».'};const save=async()=>{await Promise.all(Object.entries(vals).filter(([k])=>k in names).map(([k,v])=>api(`/api/settings/${k}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({value:+v})})));setSaved(true);setTimeout(()=>setSaved(false),1800)};return <article className="panel config"><PanelTitle title="Пороги детекции" sub="Настройте минимальную уверенность модели"/>{Object.keys(names).map(k=><label key={k}><span><b>{names[k]}</b><small>{k}</small><em className="key-hint">{descs[k]||''}</em></span><input type="range" min="10" max="100" value={Math.round(+vals[k]*100)} onChange={e=>setVals(v=>({...v,[k]:(+e.target.value/100).toFixed(2)}))}/><output>{vals[k]}</output></label>)}<button onClick={save}>{saved?<><Check size={15}/> Сохранено</>:<>Сохранить изменения</>}</button></article>}
function Customizer({close}:{close:()=>void}){const initial={...uiDefaults,...readJson('zmk_ui')};const[theme,setTheme]=useState(initial.theme);const[accent,setAccent]=useState(initial.accent);const[density,setDensity]=useState(initial.density);const[sidebar,setSidebar]=useState(initial.sidebar);const[corners,setCorners]=useState(initial.corners);const[motion,setMotion]=useState(initial.motion);const[cameraFit,setCameraFit]=useState(initial.cameraFit);const[refreshSeconds,setRefreshSeconds]=useState(String(initial.refreshSeconds));const[overviewPeriod,setOverviewPeriod]=useState(String(initial.overviewPeriod));const[overviewChart,setOverviewChart]=useState(initial.overviewChart);const[overviewStyle,setOverviewStyle]=useState(initial.overviewStyle);const[key,setKey]=useState(localStorage.getItem('zmk_api_key')||'');const current=()=>({theme,accent,density,sidebar,corners,motion,cameraFit,refreshSeconds:Number(refreshSeconds)||5,overviewPeriod:Number(overviewPeriod)||24,overviewChart,overviewStyle});const preview=(next:any)=>applyUi({...current(),...next});const choose=(kind:string,value:string)=>{if(kind==='theme')setTheme(value);if(kind==='accent')setAccent(value);if(kind==='density')setDensity(value);if(kind==='sidebar')setSidebar(value);if(kind==='corners')setCorners(value);if(kind==='motion')setMotion(value);if(kind==='cameraFit')setCameraFit(value);preview({[kind]:value})};const save=()=>{applyUi(current());if(key)localStorage.setItem('zmk_api_key',key);else localStorage.removeItem('zmk_api_key');close();location.reload()};const reset=()=>{localStorage.removeItem('zmk_ui');localStorage.removeItem('zmk_api_key');applyUi(uiDefaults);close();location.reload()};return <><div className="drawer-overlay" onClick={close}/><aside className="customizer"><div className="custom-head"><div><h2>Персонализация</h2><p>Настройте интерфейс для своей смены</p></div><button onClick={close} aria-label="Закрыть"><X/></button></div><div className="custom-section"><h3>Тема</h3><div className="choice-grid">{[['light','Светлая',Sun],['dark','Тёмная',Moon],['system','Системная',Monitor]].map(([value,label,Icon]:any)=><button key={value} className={theme===value?'selected':''} onClick={()=>choose('theme',value)}><Icon/><span>{label}</span></button>)}</div></div><div className="custom-section"><h3>Акцент</h3><div className="accents">{['lime','blue','orange','violet'].map(value=><button key={value} aria-label={value} className={`${value} ${accent===value?'selected':''}`} onClick={()=>choose('accent',value)}/>)}</div></div><div className="custom-section"><h3>Рабочее пространство</h3><div className="custom-option-grid"><label>Плотность<div className="segmented"><button className={density==='comfortable'?'active':''} onClick={()=>choose('density','comfortable')}>Комфортно</button><button className={density==='compact'?'active':''} onClick={()=>choose('density','compact')}>Компактно</button></div></label><label>Боковая панель<div className="segmented"><button className={sidebar==='full'?'active':''} onClick={()=>choose('sidebar','full')}><PanelLeft size={14}/> Полная</button><button className={sidebar==='compact'?'active':''} onClick={()=>choose('sidebar','compact')}>Иконки</button></div></label><label>Углы карточек<div className="segmented"><button className={corners==='soft'?'active':''} onClick={()=>choose('corners','soft')}>Мягкие</button><button className={corners==='square'?'active':''} onClick={()=>choose('corners','square')}>Строгие</button></div></label></div></div><div className="custom-section"><h3>Анимации</h3><div className="segmented triple"><button className={motion==='full'?'active':''} onClick={()=>choose('motion','full')}><Activity size={14}/> Полные</button><button className={motion==='reduced'?'active':''} onClick={()=>choose('motion','reduced')}>Мягкие</button><button className={motion==='off'?'active':''} onClick={()=>choose('motion','off')}>Выкл.</button></div><small>Настройка влияет на появление карточек, диаграмм и переходы интерфейса.</small></div><div className="custom-section"><h3>Камеры</h3><div className="custom-option-grid"><label>Кадр в карточке<div className="segmented"><button className={cameraFit==='cover'?'active':''} onClick={()=>choose('cameraFit','cover')}><Eye size={14}/> Заполнить</button><button className={cameraFit==='contain'?'active':''} onClick={()=>choose('cameraFit','contain')}>Без обрезки</button></div></label><label>Обновление панели<select value={refreshSeconds} onChange={e=>{setRefreshSeconds(e.target.value);preview({refreshSeconds:+e.target.value})}}><option value="5">Каждые 5 секунд</option><option value="10">Каждые 10 секунд</option><option value="30">Каждые 30 секунд</option></select></label></div></div><div className="custom-section"><h3>Обзор по умолчанию</h3><div className="custom-option-grid"><label>Период<select value={overviewPeriod} onChange={e=>{setOverviewPeriod(e.target.value);preview({overviewPeriod:+e.target.value})}}><option value="24">24 часа</option><option value="168">7 дней</option><option value="720">30 дней</option></select></label><label>Диаграмма<select value={overviewChart} onChange={e=>{setOverviewChart(e.target.value);preview({overviewChart:e.target.value})}}><option value="trend">Динамика</option><option value="types">Типы нарушений</option><option value="cameras">Камеры</option><option value="review">Решения</option><option value="severity">Критичность</option></select></label><label>Вид диаграммы<div className="segmented"><button className={overviewStyle==='bar'?'active':''} onClick={()=>{setOverviewStyle('bar');preview({overviewStyle:'bar'})}}>Столбцы</button><button className={overviewStyle==='line'?'active':''} onClick={()=>{setOverviewStyle('line');preview({overviewStyle:'line'})}}>Линия</button></div></label></div><small>Параметры обзора применятся после нажатия «Применить».</small></div><div className="custom-section"><h3>Защищённый API</h3><label className="key-input"><KeyRound/><input type="password" value={key} onChange={e=>setKey(e.target.value)} placeholder="X-API-Key (необязательно)"/></label><small>Ключ хранится только в localStorage этого браузера.</small></div><div className="custom-footer"><button onClick={reset}>Сбросить</button><button className="primary" onClick={save}>Применить</button></div></aside></>}
function TelegramMini(){const[d,setD]=useState<Dashboard|null>(null);const[events,setEvents]=useState<Event[]>([]);const[cams,setCams]=useState<Cam[]>([]);const[error,setError]=useState('');const[view,setView]=useState('Главная');const load=async()=>{setError('');try{const[a,b,c]=await Promise.all([api<Dashboard>('/api/dashboard'),api<Event[]>('/api/events?limit=20'),api<Cam[]>('/api/cameras')]);setD(a);setEvents(b);setCams(c)}catch(e){setError(e instanceof Error?e.message:'Сервис недоступен')}};useEffect(()=>{let t=0;loadTelegramSdk().then(()=>{const tg=(window as any).Telegram?.WebApp;tg?.ready();tg?.expand();load();t=window.setInterval(load,15000)});return()=>clearInterval(t)},[]);if(!d)return <div className="tg-loader">{error?<div className="api-error"><AlertTriangle/><span><b>Нет связи с API</b><small>{error}</small></span><button onClick={load}>Повторить</button></div>:<div className="loader"/>}</div>;return <div className="tgapp"><div className="tghead"><div className="brandmark"><Eye size={21}/></div><span><b>ZMK Vision</b><small>Telegram Control Center</small></span><button onClick={load}><RefreshCw size={17}/></button></div>{view==='Главная'&&<><div className="tgstate"><span className="pulse"/><div><b>Система работает штатно</b><small>{d.cameras.online}/{d.cameras.total} камер подключено</small></div></div><div className="tgmetrics"><div><Camera/><span><b>{d.cameras.online}/{d.cameras.total}</b><small>Камеры</small></span></div><div><ShieldAlert/><span><b>{d.events24h}</b><small>События</small></span></div><div><AlertTriangle/><span><b>{d.critical_unacked}</b><small>Критические</small></span></div><div><Cpu/><span><b>{d.gpu_load}%</b><small>GPU</small></span></div></div><div className="tgsection"><h3>Последние события</h3>{events.slice(0,6).map(e=><div className="tgevent" key={e.id}><i className={`sev ${e.severity}`}/><span><b>{labels[e.type]}</b><small>{e.camera_name} · {Math.round(e.confidence*100)}%</small></span><time>{new Date(e.timestamp).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</time></div>)}</div></>}{view==='Камеры'&&<div className="tgsection"><h3>Камеры</h3>{cams.map(c=><div className="tgcam" key={c.id}><div className="thumb"><Camera size={16}/><span className={c.status}/></div><span><b>{c.name}</b><small>{c.zone}</small></span><em className={c.status}>{c.status==='online'?`${c.fps} FPS`:'Офлайн'}</em></div>)}</div>}{view==='Отчёты'&&<><div className="tgsection"><h3>Отчёты и управление</h3><button className="tgaction" onClick={()=>downloadFile('/api/reports/events.csv','zmk-events.csv')}><Download/> <span><b>События CSV</b><small>Полный журнал детекций</small></span><ChevronRight/></button><button className="tgaction" onClick={()=>downloadFile('/api/reports/errors.csv?hours=24','zmk-errors.csv')}><FileWarning/> <span><b>Ошибки CSV</b><small>WARNING / ERROR / CRITICAL</small></span><ChevronRight/></button><div className="tgquality">{d.precision!==null&&d.recall!==null?<><Ring value={d.precision} label="Precision"/><Ring value={d.recall} label="Recall"/></>:<span>Модель не зарегистрирована</span>}</div></div></>}<div className="tgnav">{[['Главная',LayoutDashboard],['Камеры',Camera],['Отчёты',BarChart3]].map(([n,I]:any)=><button key={n} className={view===n?'active':''} onClick={()=>setView(n)}><I size={19}/><span>{n}</span></button>)}</div></div>}
applyUi(readJson('zmk_ui'));
const isTelegram=location.pathname.startsWith('/telegram');
createRoot(document.getElementById('root')!).render(isTelegram?<TelegramMini/>:<App/>);
